"use client"

import { useState, useEffect } from 'react';
import { Button } from '@/components/ui/button';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { Input } from '@/components/ui/input';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogTrigger } from '@/components/ui/dialog';
import { generateProductionScheduleWithAI, ProductionScheduleOutput, ScriptAnalysisInput } from '@/lib/services/schedulingGeneratorService';
import DepthSchedulingAnalysisService, { DepthSchedulingResult, SchedulingScenario, TierProgress } from '@/lib/services/depthSchedulingAnalysisService';
import { 
  Plus, 
  Share2, 
  Download, 
  Calendar, 
  Clock, 
  Users, 
  DollarSign, 
  AlertTriangle, 
  MapPin, 
  Wand2, 
  Brain, 
  CheckCircle, 
  Loader2, 
  Wrench, 
  BarChart3, 
  Zap, 
  Edit3, 
  Save, 
  X, 
  RotateCcw, 
  Code, 
  Copy, 
  ChevronDown, 
  ChevronRight, 
  ChevronUp, 
  Target, 
  TrendingUp, 
  Shield
} from 'lucide-react';
import { useSelectedProject } from '@/hooks/useSelectedProject';
import { toast } from 'sonner';
import {
  DndContext, 
  closestCenter,
  KeyboardSensor,
  PointerSensor,
  useSensor,
  useSensors,
} from '@dnd-kit/core';
import {
  arrayMove,
  SortableContext,
  sortableKeyboardCoordinates,
  verticalListSortingStrategy,
} from '@dnd-kit/sortable';
import {
  useSortable,
} from '@dnd-kit/sortable';
import { CSS } from '@dnd-kit/utilities';

// Global scheduling service lock to prevent multiple simultaneous AI calls
const SCHEDULING_LOCK_KEY = 'scheduling_ai_service_running';
const SCHEDULING_LOCK_TIMEOUT = 5 * 60 * 1000; // 5 minutes timeout
const AUTO_GENERATION_ATTEMPTED_KEY = 'scheduling_auto_generation_attempted';

// Check if scheduling service is currently running globally
const isSchedulingServiceRunning = () => {
  const lockData = localStorage.getItem(SCHEDULING_LOCK_KEY);
  if (!lockData) return false;

  try {
    const { timestamp } = JSON.parse(lockData);
    const now = Date.now();

    if (now - timestamp > SCHEDULING_LOCK_TIMEOUT) {
      localStorage.removeItem(SCHEDULING_LOCK_KEY);
      return false;
    }

    return true;
  } catch {
    localStorage.removeItem(SCHEDULING_LOCK_KEY);
    return false;
  }
};

// Set global scheduling service lock
const setSchedulingServiceLock = (projectId: string) => {
  const lockData = {
    projectId,
    timestamp: Date.now()
  };
  localStorage.setItem(SCHEDULING_LOCK_KEY, JSON.stringify(lockData));
  console.log('🔒 Scheduling AI service lock set for project:', projectId);
};

// Remove global scheduling service lock
const removeSchedulingServiceLock = () => {
  localStorage.removeItem(SCHEDULING_LOCK_KEY);
  console.log('🔓 Scheduling AI service lock removed');
};

// Sortable Scene Component for drag-and-drop
function SortableScene({ scene, index }: { scene: any, index: number }) {
  const {
    attributes,
    listeners,
    setNodeRef,
    transform,
    transition,
  } = useSortable({ id: scene.id || `scene-${index}` });

  const style = {
    transform: CSS.Transform.toString(transform),
    transition,
  };

  return (
    <div
      ref={setNodeRef}
      style={style}
      {...attributes}
      {...listeners}
      className="bg-white border rounded-lg p-4 cursor-move hover:bg-gray-50 transition-colors"
    >
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-3">
          <div className="flex items-center gap-2">
            <Calendar className="w-4 h-4 text-blue-600" />
            <span className="font-medium">Scene {scene.number || index + 1}</span>
          </div>
          <Badge variant="outline">{scene.location || 'Unknown Location'}</Badge>
        </div>
        <div className="flex items-center gap-2">
          <Badge variant="secondary">{scene.timeOfDay || 'Day'}</Badge>
          <div className="text-sm text-muted-foreground">
            {scene.estimatedDuration || '30'} min
          </div>
        </div>
      </div>

      <div className="mt-2">
        <p className="text-sm text-muted-foreground line-clamp-2">
          {scene.description || scene.summary || 'No description available'}
        </p>
      </div>

      {scene.characters && scene.characters.length > 0 && (
        <div className="mt-3 flex flex-wrap gap-1">
          {scene.characters.slice(0, 3).map((character: string, i: number) => (
            <Badge key={i} variant="outline" className="text-xs">
              {character}
            </Badge>
          ))}
          {scene.characters.length > 3 && (
            <Badge variant="outline" className="text-xs">
              +{scene.characters.length - 3} more
            </Badge>
          )}
        </div>
      )}
    </div>
  );
}

export default function SchedulePage() {
  const { selectedProject } = useSelectedProject();

  const [activeView, setActiveView] = useState<'overview' | 'schedule' | 'cast' | 'locations' | 'equipment' | 'conflicts' | 'optimization' | 'depth-analysis'>('overview');
  const [productionSchedule, setProductionSchedule] = useState<ProductionScheduleOutput | null>(null);
  const [originalSchedule, setOriginalSchedule] = useState<ProductionScheduleOutput | null>(null);
  const [isGeneratingSchedule, setIsGeneratingSchedule] = useState(false);
  const [scheduleError, setScheduleError] = useState('');
  const [hasUnsavedChanges, setHasUnsavedChanges] = useState(false);

  // Depth Analysis State
  const [depthSchedulingResults, setDepthSchedulingResults] = useState<DepthSchedulingResult | null>(null);
  const [isDepthAnalyzing, setIsDepthAnalyzing] = useState(false);
  const [depthAnalysisError, setDepthAnalysisError] = useState('');
  const [tierProgress, setTierProgress] = useState<TierProgress[]>([]);
  const [currentTier, setCurrentTier] = useState('');
  const [optimizationScenarios, setOptimizationScenarios] = useState<SchedulingScenario[]>([]);

  // Scene management for drag-and-drop
  const [scenes, setScenes] = useState<any[]>([]);
  const [selectedScenes, setSelectedScenes] = useState<string[]>([]);

  // Drag and drop sensors
  const sensors = useSensors(
    useSensor(PointerSensor),
    useSensor(KeyboardSensor, {
      coordinateGetter: sortableKeyboardCoordinates,
    })
  );

  // Load existing schedule on component mount
  useEffect(() => {
    if (selectedProject) {
      const storedSchedule = localStorage.getItem(`schedule_${selectedProject.id}`);
      if (storedSchedule) {
        try {
          const schedule = JSON.parse(storedSchedule);
          setProductionSchedule(schedule);
          setOriginalSchedule(schedule);

          // Extract scenes for drag-and-drop
          if (schedule.shootingDays) {
            const allScenes = schedule.shootingDays.flatMap((day: any) => 
              day.scenes || []
            );
            setScenes(allScenes);
          }
        } catch (error) {
          console.error('Error loading stored schedule:', error);
        }
      }

      const storedDepthResults = localStorage.getItem(`depth_schedule_${selectedProject.id}`);
      if (storedDepthResults) {
        try {
          const results = JSON.parse(storedDepthResults);
          setDepthSchedulingResults(results);
        } catch (error) {
          console.error('Error loading stored depth scheduling results:', error);
        }
      }
    }
  }, [selectedProject]);

  // Generate basic production schedule
  const handleGenerateSchedule = async () => {
    if (!selectedProject?.scriptContent) {
      toast.error("No script content available for scheduling");
      return;
    }

    if (isSchedulingServiceRunning()) {
      toast.warning("Schedule generation already in progress. Please wait...");
      return;
    }

    setIsGeneratingSchedule(true);
    setScheduleError('');
    setSchedulingServiceLock(selectedProject.id);

    try {
      console.log('📅 Starting schedule generation');

      // Get analysis data if available
      const analysisData = localStorage.getItem(`pdf_analysis_${selectedProject.id}`);
      let parsedAnalysis = null;
      try {
        parsedAnalysis = analysisData ? JSON.parse(analysisData) : null;
      } catch (e) {
        console.warn('Could not parse analysis data');
      }

      const input: ScriptAnalysisInput = {
        script: selectedProject.scriptContent,
        scenes: parsedAnalysis?.data?.scenes || [],
        characters: parsedAnalysis?.data?.characters || [],
        locations: parsedAnalysis?.data?.locations || []
      };

      const result = await generateProductionScheduleWithAI(input);

      if (result.success && result.data) {
        setProductionSchedule(result.data);
        setOriginalSchedule(result.data);

        // Extract scenes for drag-and-drop
        if (result.data.shootingDays) {
          const allScenes = result.data.shootingDays.flatMap((day: any) => 
            day.scenes || []
          );
          setScenes(allScenes);
        }

        // Store results
        localStorage.setItem(`schedule_${selectedProject.id}`, JSON.stringify(result.data));

        toast.success("Production Schedule Generated!", {
          description: `Created ${result.data.shootingDays?.length || 0} shooting days`,
        });
      } else {
        throw new Error(result.error || 'Schedule generation failed');
      }
    } catch (error) {
      console.error('Schedule generation error:', error);
      const errorMessage = error instanceof Error ? error.message : 'Schedule generation failed';
      setScheduleError(errorMessage);

      toast.error("Schedule Generation Failed", {
        description: errorMessage,
      });
    } finally {
      setIsGeneratingSchedule(false);
      removeSchedulingServiceLock();
    }
  };

  // Handle depth scheduling analysis
  const handleDepthAnalysis = async () => {
    if (!selectedProject?.scriptContent) {
      toast.error("No script content available for analysis");
      return;
    }

    setIsDepthAnalyzing(true);
    setDepthAnalysisError('');
    setTierProgress([]);
    setCurrentTier('');

    try {
      console.log('🧠 Starting depth scheduling analysis');

      const result = await DepthSchedulingAnalysisService.analyze(
        selectedProject.scriptContent,
        selectedProject.id,
        (tier, progress) => {
          setCurrentTier(tier);
          setTierProgress(prev => {
            const updated = [...prev];
            const existing = updated.find(p => p.tier === tier);
            if (existing) {
              existing.progress = progress;
            } else {
              updated.push({ tier, progress });
            }
            return updated;
          });
        }
      );

      if (result.success && result.data) {
        setDepthSchedulingResults(result.data);

        if (result.data.optimizationScenarios) {
          setOptimizationScenarios(result.data.optimizationScenarios);
        }

        // Store results
        localStorage.setItem(`depth_schedule_${selectedProject.id}`, JSON.stringify(result.data));

        toast.success("Depth Scheduling Analysis Complete!", {
          description: "4-tier scheduling analysis completed successfully",
        });
      } else {
        throw new Error(result.error || 'Depth analysis failed');
      }
    } catch (error) {
      console.error('Depth scheduling analysis error:', error);
      const errorMessage = error instanceof Error ? error.message : 'Depth analysis failed';
      setDepthAnalysisError(errorMessage);

      toast.error("Depth Analysis Failed", {
        description: errorMessage,
      });
    } finally {
      setIsDepthAnalyzing(false);
      setTierProgress([]);
      setCurrentTier('');
    }
  };

  // Handle drag end for scene reordering
  const handleDragEnd = (event: any) => {
    const { active, over } = event;

    if (active.id !== over.id) {
      setScenes((items) => {
        const oldIndex = items.findIndex(item => (item.id || `scene-${items.indexOf(item)}`) === active.id);
        const newIndex = items.findIndex(item => (item.id || `scene-${items.indexOf(item)}`) === over.id);

        const newItems = arrayMove(items, oldIndex, newIndex);
        setHasUnsavedChanges(true);
        return newItems;
      });
    }
  };

  // Save schedule changes
  const handleSaveSchedule = () => {
    if (!selectedProject || !productionSchedule) return;

    // Update schedule with reordered scenes
    const updatedSchedule = {
      ...productionSchedule,
      shootingDays: productionSchedule.shootingDays?.map((day: any, dayIndex: number) => ({
        ...day,
        scenes: scenes.filter((_, sceneIndex) => 
          Math.floor(sceneIndex / (scenes.length / (productionSchedule.shootingDays?.length || 1))) === dayIndex
        )
      }))
    };

    setProductionSchedule(updatedSchedule);
    localStorage.setItem(`schedule_${selectedProject.id}`, JSON.stringify(updatedSchedule));
    setHasUnsavedChanges(false);

    toast.success("Schedule saved successfully!");
  };

  // Export schedule
  const exportSchedule = () => {
    if (!productionSchedule || !selectedProject) return;

    const exportData = {
      project: selectedProject.name,
      timestamp: new Date().toISOString(),
      schedule: productionSchedule,
      totalDays: productionSchedule.shootingDays?.length || 0,
      totalScenes: scenes.length
    };

    const blob = new Blob([JSON.stringify(exportData, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `production-schedule-${selectedProject.name || 'project'}.json`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);

    toast.success("Schedule exported successfully!");
  };

  if (!selectedProject) {
    return (
      <div className="container mx-auto px-4 py-8">
        <Card>
          <CardContent className="flex flex-col items-center justify-center h-64 text-center">
            <Calendar className="h-12 w-12 text-muted-foreground mb-4" />
            <h3 className="text-xl font-medium mb-2">No Project Selected</h3>
            <p className="text-muted-foreground mb-4">Select a project to create its production schedule</p>
            <Button asChild>
              <a href="/dashboard/admin/upload-script">Create Project</a>
            </Button>
          </CardContent>
        </Card>
      </div>
    );
  }

  return (
    <div className="container mx-auto px-4 py-8">
      <div className="max-w-7xl mx-auto">
        {/* Header */}
        <div className="flex items-center justify-between mb-8">
          <div>
            <h1 className="text-3xl font-bold">📅 Production Scheduling</h1>
            <p className="text-muted-foreground mt-2">
              Project: {selectedProject.name}
            </p>
          </div>
          <div className="flex items-center gap-3">
            {hasUnsavedChanges && (
              <Button variant="outline" onClick={handleSaveSchedule}>
                <Save className="w-4 h-4 mr-2" />
                Save Changes
              </Button>
            )}
            {productionSchedule && (
              <Button variant="outline" onClick={exportSchedule}>
                <Download className="w-4 h-4 mr-2" />
                Export Schedule
              </Button>
            )}
            <Button onClick={handleGenerateSchedule} disabled={isGeneratingSchedule}>
              {isGeneratingSchedule ? (
                <>
                  <Loader2 className="w-4 h-4 mr-2 animate-spin" />
                  Generating...
                </>
              ) : (
                <>
                  <Wand2 className="w-4 h-4 mr-2" />
                  Generate Schedule
                </>
              )}
            </Button>
          </div>
        </div>

        {/* View Navigation */}
        <div className="border-b border-gray-200 mb-8">
          <nav className="-mb-px flex space-x-8 overflow-x-auto">
            {[
              { id: 'overview', label: 'Overview', icon: BarChart3 },
              { id: 'schedule', label: 'Schedule', icon: Calendar },
              { id: 'cast', label: 'Cast', icon: Users },
              { id: 'locations', label: 'Locations', icon: MapPin },
              { id: 'equipment', label: 'Equipment', icon: Wrench },
              { id: 'conflicts', label: 'Conflicts', icon: AlertTriangle },
              { id: 'optimization', label: 'Optimization', icon: Target },
              { id: 'depth-analysis', label: 'Depth Analysis', icon: Brain },
            ].map((view) => {
              const Icon = view.icon;
              return (
                <button
                  key={view.id}
                  onClick={() => setActiveView(view.id as any)}
                  className={`py-2 px-1 border-b-2 font-medium text-sm whitespace-nowrap ${
                    activeView === view.id
                      ? 'border-blue-500 text-blue-600'
                      : 'border-transparent text-gray-500 hover:text-gray-700 hover:border-gray-300'
                  }`}
                >
                  <Icon className="w-4 h-4 mr-2 inline" />
                  {view.label}
                </button>
              );
            })}
          </nav>
        </div>

        {/* View Content */}
        {activeView === 'overview' && (
          <div className="space-y-6">
            {!productionSchedule && (
              <Card>
                <CardHeader>
                  <CardTitle>Production Schedule Overview</CardTitle>
                </CardHeader>
                <CardContent>
                  <div className="text-center py-8">
                    <Calendar className="w-12 h-12 text-muted-foreground mx-auto mb-4" />
                    <h3 className="text-lg font-medium mb-2">No Schedule Generated</h3>
                    <p className="text-muted-foreground mb-4">
                      Generate a production schedule to see the overview
                    </p>
                    <Button onClick={handleGenerateSchedule} disabled={isGeneratingSchedule}>
                      {isGeneratingSchedule ? (
                        <>
                          <Loader2 className="w-4 h-4 mr-2 animate-spin" />
                          Generating Schedule...
                        </>
                      ) : (
                        <>
                          <Wand2 className="w-4 h-4 mr-2" />
                          Generate Schedule
                        </>
                      )}
                    </Button>
                  </div>
                </CardContent>
              </Card>
            )}

            {productionSchedule && (
              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
                <Card>
                  <CardContent className="p-6">
                    <div className="text-center">
                      <div className="text-3xl font-bold text-blue-600">
                        {productionSchedule.shootingDays?.length || 0}
                      </div>
                      <div className="text-sm text-muted-foreground">Shooting Days</div>
                    </div>
                  </CardContent>
                </Card>
                <Card>
                  <CardContent className="p-6">
                    <div className="text-center">
                      <div className="text-3xl font-bold text-green-600">
                        {scenes.length}
                      </div>
                      <div className="text-sm text-muted-foreground">Total Scenes</div>
                    </div>
                  </CardContent>
                </Card>
                <Card>
                  <CardContent className="p-6">
                    <div className="text-center">
                      <div className="text-3xl font-bold text-orange-600">
                        {productionSchedule.estimatedBudget || 'N/A'}
                      </div>
                      <div className="text-sm text-muted-foreground">Est. Budget</div>
                    </div>
                  </CardContent>
                </Card>
                <Card>
                  <CardContent className="p-6">
                    <div className="text-center">
                      <div className="text-3xl font-bold text-purple-600">
                        {productionSchedule.crewSize || 'N/A'}
                      </div>
                      <div className="text-sm text-muted-foreground">Crew Size</div>
                    </div>
                  </CardContent>
                </Card>
              </div>
            )}

            {scheduleError && (
              <Card className="border-red-200">
                <CardContent className="p-6">
                  <div className="text-center text-red-600">
                    <AlertTriangle className="w-8 h-8 mx-auto mb-4" />
                    <h3 className="text-lg font-medium mb-2">Schedule Generation Failed</h3>
                    <p>{scheduleError}</p>
                  </div>
                </CardContent>
              </Card>
            )}
          </div>
        )}

        {activeView === 'schedule' && (
          <div className="space-y-6">
            {productionSchedule && scenes.length > 0 ? (
              <div className="space-y-6">
                <Card>
                  <CardHeader>
                    <div className="flex items-center justify-between">
                      <CardTitle>Scene Schedule</CardTitle>
                      <div className="flex items-center gap-2">
                        {hasUnsavedChanges && (
                          <Badge variant="outline" className="text-orange-600">
                            Unsaved Changes
                          </Badge>
                        )}
                        <Button variant="outline" size="sm" onClick={handleSaveSchedule} disabled={!hasUnsavedChanges}>
                          <Save className="w-4 h-4 mr-2" />
                          Save
                        </Button>
                      </div>
                    </div>
                  </CardHeader>
                  <CardContent>
                    <p className="text-sm text-muted-foreground mb-4">
                      Drag and drop scenes to reorder the shooting schedule
                    </p>

                    <DndContext 
                      sensors={sensors}
                      collisionDetection={closestCenter}
                      onDragEnd={handleDragEnd}
                    >
                      <SortableContext 
                        items={scenes.map((scene, index) => scene.id || `scene-${index}`)}
                        strategy={verticalListSortingStrategy}
                      >
                        <div className="space-y-3">
                          {scenes.map((scene, index) => (
                            <SortableScene key={scene.id || `scene-${index}`} scene={scene} index={index} />
                          ))}
                        </div>
                      </SortableContext>
                    </DndContext>
                  </CardContent>
                </Card>
              </div>
            ) : (
              <Card>
                <CardContent className="p-6">
                  <div className="text-center">
                    <Calendar className="w-12 h-12 text-muted-foreground mx-auto mb-4" />
                    <h3 className="text-lg font-medium mb-2">No Schedule Available</h3>
                    <p className="text-muted-foreground">Generate a production schedule to view scenes</p>
                  </div>
                </CardContent>
              </Card>
            )}
          </div>
        )}

        {activeView === 'depth-analysis' && (
          <div className="space-y-6">
            <Card>
              <CardHeader>
                <CardTitle>Depth Scheduling Analysis</CardTitle>
                <p className="text-sm text-muted-foreground">
                  Advanced 4-tier scheduling analysis with optimization scenarios
                </p>
              </CardHeader>
              <CardContent>
                <div className="space-y-4">
                  <Button
                    onClick={handleDepthAnalysis}
                    disabled={isDepthAnalyzing || !selectedProject?.scriptContent}
                    className="w-full"
                  >
                    {isDepthAnalyzing ? (
                      <>
                        <Loader2 className="w-4 h-4 mr-2 animate-spin" />
                        Running Depth Analysis...
                      </>
                    ) : (
                      <>
                        <Brain className="w-4 h-4 mr-2" />
                        Start Depth Analysis
                      </>
                    )}
                  </Button>

                  {isDepthAnalyzing && (
                    <div className="space-y-4">
                      <div className="text-sm font-medium">Current Tier: {currentTier}</div>
                      {tierProgress.map((tier) => (
                        <div key={tier.tier} className="space-y-2">
                          <div className="flex justify-between text-sm">
                            <span>{tier.tier}</span>
                            <span>{tier.progress}%</span>
                          </div>
                          <div className="w-full bg-gray-200 rounded-full h-2">
                            <div
                              className="bg-blue-600 h-2 rounded-full transition-all duration-300"
                              style={{ width: `${tier.progress}%` }}
                            />
                          </div>
                        </div>
                      ))}
                    </div>
                  )}

                  {depthAnalysisError && (
                    <div className="text-red-600 text-sm">
                      <AlertTriangle className="w-4 h-4 mr-2 inline" />
                      {depthAnalysisError}
                    </div>
                  )}
                </div>
              </CardContent>
            </Card>

            {depthSchedulingResults && (
              <div className="space-y-6">
                <Card>
                  <CardHeader>
                    <CardTitle className="flex items-center gap-2">
                      <CheckCircle className="w-5 h-5 text-green-600" />
                      Depth Analysis Results
                    </CardTitle>
                  </CardHeader>
                  <CardContent>
                    <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
                      <div className="text-center">
                        <div className="text-2xl font-bold text-blue-600">
                          {depthSchedulingResults.recommendedDays || 0}
                        </div>
                        <div className="text-sm text-muted-foreground">Recommended Days</div>
                      </div>
                      <div className="text-center">
                        <div className="text-2xl font-bold text-green-600">
                          {depthSchedulingResults.efficiency || 0}%
                        </div>
                        <div className="text-sm text-muted-foreground">Efficiency</div>
                      </div>
                      <div className="text-center">
                        <div className="text-2xl font-bold text-orange-600">
                          {optimizationScenarios.length}
                        </div>
                        <div className="text-sm text-muted-foreground">Scenarios</div>
                      </div>
                      <div className="text-center">
                        <div className="text-2xl font-bold text-purple-600">
                          4
                        </div>
                        <div className="text-sm text-muted-foreground">Analysis Tiers</div>
                      </div>
                    </div>
                  </CardContent>
                </Card>

                {optimizationScenarios.length > 0 && (
                  <Card>
                    <CardHeader>
                      <CardTitle>Optimization Scenarios</CardTitle>
                    </CardHeader>
                    <CardContent>
                      <div className="grid gap-4">
                        {optimizationScenarios.map((scenario, index) => (
                          <div key={index} className="border rounded-lg p-4">
                            <div className="flex items-center justify-between mb-2">
                              <h4 className="font-medium">{scenario.name}</h4>
                              <Badge variant={scenario.priority === 'high' ? 'destructive' : scenario.priority === 'medium' ? 'default' : 'secondary'}>
                                {scenario.priority} priority
                              </Badge>
                            </div>
                            <p className="text-sm text-muted-foreground mb-2">
                              {scenario.description}
                            </p>
                            <div className="flex items-center gap-4 text-sm">
                              <div className="flex items-center gap-1">
                                <TrendingUp className="w-4 h-4 text-green-600" />
                                <span>Cost: {scenario.estimatedCost}</span>
                              </div>
                              <div className="flex items-center gap-1">
                                <Clock className="w-4 h-4 text-blue-600" />
                                <span>Time: {scenario.timeImpact}</span>
                              </div>
                            </div>
                          </div>
                        ))}
                      </div>
                    </CardContent>
                  </Card>
                )}
              </div>
            )}
          </div>
        )}

        {/* Other view placeholders */}
        {['cast', 'locations', 'equipment', 'conflicts', 'optimization'].includes(activeView) && (
          <Card>
            <CardHeader>
              <CardTitle className="capitalize">{activeView} Management</CardTitle>
            </CardHeader>
            <CardContent>
              <div className="text-center py-8">
                <div className="text-muted-foreground">
                  {activeView.charAt(0).toUpperCase() + activeView.slice(1)} management features will be available after schedule generation.
                </div>
              </div>
            </CardContent>
          </Card>
        )}
      </div>
    </div>
  );
}

tool_input.content:
"use client"

import { useState, useEffect } from 'react';
import { Button } from '@/components/ui/button';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { Textarea } from '@/components/ui/textarea';
import { CategoryBadge } from '@/components/ui/CategoryBadge';
import { 
  Plus, 
  Share2, 
  Download, 
  Settings, 
  Search, 
  FileText, 
  Loader2, 
  Wand2, 
  Brain, 
  BarChart3, 
  Clock, 
  Users, 
  MapPin, 
  DollarSign, 
  AlertTriangle, 
  Code, 
  CheckCircle, 
  RotateCcw, 
  ChevronDown, 
  ChevronRight, 
  Copy,
  Calculator,
  TrendingUp,
  Shield,
  Building,
  Zap
} from 'lucide-react';
import { analyzeBudgetCoordinatorWithAI, BudgetCoordinatorOutput } from '@/lib/services/budgetCoordinatorService';
import { analyzeLaborCostWithAI, LaborCostOutput } from '@/lib/services/laborCostService';
import { analyzeEquipmentPricingWithAI, EquipmentPricingOutput } from '@/lib/services/equipmentPricingService';
import { analyzeLocationCostWithAI, LocationCostOutput } from '@/lib/services/locationCostService';
import { analyzeScheduleOptimizerWithAI, ScheduleOptimizerOutput } from '@/lib/services/scheduleOptimizerService';
import { analyzeInsuranceCalculatorWithAI, InsuranceCalculatorOutput } from '@/lib/services/insuranceCalculatorService';
import { analyzePostProductionEstimatorWithAI, PostProductionEstimatorOutput } from '@/lib/services/postProductionEstimatorService';
import { analyzeTaxIncentiveAnalyzerWithAI, TaxIncentiveAnalyzerOutput } from '@/lib/services/taxIncentiveAnalyzerService';
import { analyzeBudgetAggregatorWithAI, BudgetAggregatorOutput } from '@/lib/services/budgetAggregatorService';
import { analyzeCashFlowProjectorWithAI, CashFlowProjectorOutput } from '@/lib/services/cashFlowProjectorService';
import { generateBasicBudgetWithAI, BasicBudgetOutput } from '@/lib/services/basicBudgetGeneratorService';
import { analyzeBudgetMasterWithAI, ComprehensiveBudgetMasterOutput } from '@/lib/services/aiBudgetMasterService';
import { useSelectedProject } from '@/hooks/useSelectedProject';
import { toast } from 'sonner';

export default function BudgetPage() {
  console.log('💰 ENHANCED BUDGETING PAGE: Component rendering at', new Date().toISOString());

  const { selectedProject } = useSelectedProject();
  const [activeTab, setActiveTab] = useState('basicBudget');
  const [showFringes, setShowFringes] = useState(false);
  const [fringeSearch, setFringeSearch] = useState('');

  // Budget 1 - Budget Coordinator state
  const [jsonInputBudgetCoordinator, setJsonInputBudgetCoordinator] = useState('');
  const [isAnalyzingBudgetCoordinator, setIsAnalyzingBudgetCoordinator] = useState(false);
  const [budgetCoordinatorResult, setBudgetCoordinatorResult] = useState<BudgetCoordinatorOutput | null>(null);
  const [budgetCoordinatorError, setBudgetCoordinatorError] = useState('');

  // Budget 2 - Labor Cost Calculator state
  const [jsonInputLaborCost, setJsonInputLaborCost] = useState('');
  const [isAnalyzingLaborCost, setIsAnalyzingLaborCost] = useState(false);
  const [laborCostResult, setLaborCostResult] = useState<LaborCostOutput | null>(null);
  const [laborCostError, setLaborCostError] = useState('');
  const [laborCostRawResponse, setLaborCostRawResponse] = useState<string>('');

  // Budget 3 - Equipment Pricing Engine state
  const [jsonInputEquipmentPricing, setJsonInputEquipmentPricing] = useState('');
  const [isAnalyzingEquipmentPricing, setIsAnalyzingEquipmentPricing] = useState(false);
  const [equipmentPricingResult, setEquipmentPricingResult] = useState<EquipmentPricingOutput | null>(null);
  const [equipmentPricingError, setEquipmentPricingError] = useState('');
  const [equipmentPricingRawResponse, setEquipmentPricingRawResponse] = useState<string>('');

  // Budget 4 - Location Cost Estimator state
  const [jsonInputLocationCost, setJsonInputLocationCost] = useState('');
  const [isAnalyzingLocationCost, setIsAnalyzingLocationCost] = useState(false);
  const [locationCostResult, setLocationCostResult] = useState<LocationCostOutput | null>(null);
  const [locationCostError, setLocationCostError] = useState('');
  const [locationCostRawResponse, setLocationCostRawResponse] = useState<string>('');

  // Budget 5 - Schedule Optimizer state
  const [jsonInputScheduleOptimizer, setJsonInputScheduleOptimizer] = useState('');
  const [isAnalyzingScheduleOptimizer, setIsAnalyzingScheduleOptimizer] = useState(false);
  const [scheduleOptimizerResult, setScheduleOptimizerResult] = useState<ScheduleOptimizerOutput | null>(null);
  const [scheduleOptimizerError, setScheduleOptimizerError] = useState('');
  const [scheduleOptimizerRawResponse, setScheduleOptimizerRawResponse] = useState<string>('');

  // Budget 6 - Insurance Calculator state
  const [jsonInputInsuranceCalculator, setJsonInputInsuranceCalculator] = useState('');
  const [isAnalyzingInsuranceCalculator, setIsAnalyzingInsuranceCalculator] = useState(false);
  const [insuranceCalculatorResult, setInsuranceCalculatorResult] = useState<InsuranceCalculatorOutput | null>(null);
  const [insuranceCalculatorError, setInsuranceCalculatorError] = useState('');
  const [insuranceCalculatorRawResponse, setInsuranceCalculatorRawResponse] = useState<string>('');

  // Budget 7 - Post-Production Estimator state
  const [jsonInputPostProductionEstimator, setJsonInputPostProductionEstimator] = useState('');
  const [isAnalyzingPostProductionEstimator, setIsAnalyzingPostProductionEstimator] = useState(false);
  const [postProductionEstimatorResult, setPostProductionEstimatorResult] = useState<PostProductionEstimatorOutput | null>(null);
  const [postProductionEstimatorError, setPostProductionEstimatorError] = useState('');
  const [postProductionEstimatorRawResponse, setPostProductionEstimatorRawResponse] = useState<string>('');

  // Budget 8 - Tax Incentive Analyzer state
  const [jsonInputTaxIncentiveAnalyzer, setJsonInputTaxIncentiveAnalyzer] = useState('');
  const [isAnalyzingTaxIncentiveAnalyzer, setIsAnalyzingTaxIncentiveAnalyzer] = useState(false);
  const [taxIncentiveAnalyzerResult, setTaxIncentiveAnalyzerResult] = useState<TaxIncentiveAnalyzerOutput | null>(null);
  const [taxIncentiveAnalyzerError, setTaxIncentiveAnalyzerError] = useState('');
  const [taxIncentiveAnalyzerRawResponse, setTaxIncentiveAnalyzerRawResponse] = useState<string>('');

  // Budget 9 - Budget Aggregator state
  const [jsonInputBudgetAggregator, setJsonInputBudgetAggregator] = useState('');
  const [isAnalyzingBudgetAggregator, setIsAnalyzingBudgetAggregator] = useState(false);
  const [budgetAggregatorResult, setBudgetAggregatorResult] = useState<BudgetAggregatorOutput | null>(null);
  const [budgetAggregatorError, setBudgetAggregatorError] = useState('');
  const [budgetAggregatorRawResponse, setBudgetAggregatorRawResponse] = useState<string>('');

  // Budget 10 - Cash Flow Projector state
  const [jsonInputCashFlowProjector, setJsonInputCashFlowProjector] = useState('');
  const [isAnalyzingCashFlowProjector, setIsAnalyzingCashFlowProjector] = useState(false);
  const [cashFlowProjectorResult, setCashFlowProjectorResult] = useState<CashFlowProjectorOutput | null>(null);
