        {/* Tab Content */}
        {activeTab === 'basicBudget' && (
          <div className="space-y-6">
            <Card>
              <CardHeader>
                <CardTitle>Basic Budget Generator</CardTitle>
                <p className="text-sm text-muted-foreground">
