    highComplexityScenes: number[];
    specialSchedulingNeeds: string[];
    potentialBottlenecks: string[];
    timingRiskFactors: string[];
  };
  qualityControlChecks: {
    dataValidation: 'PASS' | 'FAIL';
    timingConsistency: 'PASS' | 'FAIL';
