        console.log('📄 Raw response (first 500 chars):', response.substring(0, 500));
        parsedResult = null;
      }

      // Handle multiple possible response structures with robust fallbacks
      let coordinatorOutput;
      if (parsedResult && parsedResult.coordinatorOutput) {
