        recommendedScenario: 'baseline',
        summary: {
          optimalScheduleDays: 0,
          estimatedBudgetRange: 'Analysis Failed',
          majorRisks: ['Pipeline execution error'],
          complianceStatus: 'Analysis incomplete'
        }
      };
    }
  }

