            <Button
              onClick={() => navigate('/create-project')}
              className="bg-purple-600 hover:bg-purple-700 text-white flex items-center space-x-2"
            >
              <Plus className="h-4 w-4" />
              <span>Create Project ({projects.length} of 1)</span>
            </Button>
          </div>
        </div>

        {/* Projects Grid */}
