   * Check if CJS API is available
   */
  async checkApiHealth(): Promise<boolean> {
    const now = Date.now();

    // Cache health check for 1 minute
    if (this.isApiAvailable !== null && (now - this.lastHealthCheck) < this.healthCheckInterval) {
      return this.isApiAvailable;
    }

