      });

      clearTimeout(timeoutId);

      if (response.ok) {
        this.isApiAvailable = true;
        this.lastHealthCheck = now;
        console.log('✅ CJS API is available');
        return true;
      } else {
        throw new Error(`Health check failed: ${response.status}`);
      }
