const CJS_API_BASE_URL = 'http://localhost:3001';
const CJS_API_TIMEOUT = 30000; // 30 seconds timeout

export interface CJSAnalysisResponse {
  success: boolean;
  data?: {
    totalScenes: number;
    totalCharacters: number;
