import { useSelectedProject } from '@/hooks/useSelectedProject';
import { toast } from 'sonner';
import { 
  Search, 
  FileText, 
  Share2, 
  Download, 
  Upload, 
  Edit3, 
  Save, 
  RotateCcw, 
  Eye, 
  FileEdit, 
  AlertCircle, 
