    }
  },
  "dailySchedule": [
    {
      "day": "number",
      "date": "YYYY-MM-DD",
      "location": "string",
      "scenes": [
        {
          "sceneNumber": "number",
          "startTime": "HH:MM",
          "endTime": "HH:MM", 
          "duration": "number_hours"
        }
      ],
      "castNeeded": ["array_of_character_names"],
      "crewSize": "number",
      "estimatedCost": "number"
    }
  ],
  "castSchedule": [
    {
      "characterName": "string",
      "workDays": ["array_of_day_numbers"],
      "totalDays": "number",
