                          <div>
                            <h3 className="text-lg font-semibold text-white">{cast.characterName}</h3>
                          </div>
                          <div className="text-right">
                            <div className="text-white font-medium">{cast.totalDays} days</div>
                            <div className="text-gray-400 text-sm">${typeof cast.estimatedCost === 'number' ? new Intl.NumberFormat('en-US').format(cast.estimatedCost) : cast.estimatedCost}</div>
