                </div>
              </CardContent>
            </Card>
          </div>
        )}

        {activeView === 'optimization' && (
          <div className="space-y-6">
            <Card>
              <CardContent className="p-6">
                <div className="text-center">
                  <Target className="w-12 h-12 text-muted-foreground mx-auto mb-4" />
