                          <p className="text-muted-foreground text-sm">Crew Size</p>
                          <p className="text-2xl font-bold">{productionSchedule.scheduleOverview?.recommendedCrewSize || 'N/A'}</p>
                        </div>
                        <Users className="h-8 w-8 text-blue-600" />
