                          <div className="text-right">
                            <div className="text-white font-medium">${typeof equipment.estimatedCost === 'number' ? new Intl.NumberFormat('en-US').format(equipment.estimatedCost) : equipment.estimatedCost}</div>
                            <div className="text-gray-400 text-sm">{equipment.rentalDays || 0} days</div>
                          </div>
                        </div>

                        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                          <div>
                            <div className="text-gray-400 text-sm font-medium mb-1">Scenes Required</div>
                            <div className="text-white">{equipment.scenesRequired?.join(', ') || 'N/A'}</div>
                          </div>
                          <div>
                            <div className="text-gray-400 text-sm font-medium mb-1">Rental Days</div>
                            <div className="text-white">{equipment.days?.join(', ') || equipment.rentalDays || 'N/A'}</div>
                          </div>
                        </div>

                        {equipment.specifications && (
                          <div className="mt-3">
                            <div className="text-gray-400 text-sm font-medium mb-1">Specifications</div>
                            <div className="text-gray-300 text-sm">{equipment.specifications}</div>
                          </div>
                        )}
                      </div>
                    ))}
                  </div>
                </CardContent>
              </Card>
            ) : (
              <Card>
                <CardContent className="p-6">
                  <div className="text-center">
                    <Wrench className="w-12 h-12 text-muted-foreground mx-auto mb-4" />
                    <h3 className="text-lg font-medium mb-2">No Equipment Schedule Available</h3>
                    <p className="text-muted-foreground">Generate a production schedule to view equipment details</p>
                  </div>
                </CardContent>
              </Card>
            )}
          </div>
        )}

        {activeView === 'conflicts' && (
          <div className="space-y-6">
            <Card>
              <CardContent className="p-6">
                <div className="text-center">
                  <AlertTriangle className="w-12 h-12 text-muted-foreground mx-auto mb-4" />
                  <h3 className="text-lg font-medium mb-2">Conflicts Analysis</h3>
                  <p className="text-muted-foreground">Schedule conflicts will be displayed here once generated</p>
