        name: 'Tax Incentive Analyzer'
      },
      aggregator: {
        service: analyzeBudgetAggregatorWithAI,
        setAnalyzing: setIsAnalyzingBudgetAggregator,
        setResult: setBudgetAggregatorResult,
        setError: setBudgetAggregatorError,
