        name: 'Budget Aggregator'
      },
      cashflow: {
        service: analyzeCashFlowProjectorWithAI,
        setAnalyzing: setIsAnalyzingCashFlowProjector,
        setResult: setCashFlowProjectorResult,
        setError: setCashFlowProjectorError,
