        { key: 'insurance', setter: setInsuranceCalculatorResult },
        { key: 'postprod', setter: setPostProductionEstimatorResult },
        { key: 'tax', setter: setTaxIncentiveAnalyzerResult },
        { key: 'aggregator', setter: setBudgetAggregatorResult },
