savedChanges, setHasUnsavedChanges] = useState(false);\n  const [isEditMode, setIsEditMode] = useState(false);\n  const [currentPage, setCurrentPage] = useState(1);\n  const [linesPerPage] = useState(50);\n\n  // PDF analysis state\n  const [pdfAnalysisResults, setPdfAnalysisResults] = useState<any | null>(null);\n  const [isPdfAnalyzing, setIsPdfAnalyzing] = useState(false);\n  const [pdfAnalysisError, setPdfAnalysisError] = useState('');\n  const [uploadedPdfName, setUploadedPdfName] = useState('');\n  const [showRawResponse, setShowRawResponse] = useState(false);\n\n  // Background processing state\n  const [isGeneratingSchedule, setIsGeneratingSchedule] = useState(false);\n  const [isGeneratingBudget, setIsGeneratingBudget] = useState(false);\n  const [backgroundProcessStatus, setBackgroundProcessStatus] = useState('');\n  const [backgroundProcessComplete, setBackgroundProcessComplete] = useState(false);\n\n  // Depth Analysis state\n  const [depthAnalysisResults, setDepthAnalysisResults] = useState<CoordinatorOutput | null>(null);\n  const [isDepthAnalyzing, setIsDepthAnalyzing] = useState(false);\n  const [depthAnalysisError, setDepthAnalysisError] = useState('');\n  const [depthAnalysisProgress, setDepthAnalysisProgress] = useState(0);\n  const [currentDepthAgent, setCurrentDepthAgent] = useState('');\n  const [showDepthResults, setShowDepthResults] = useState(false);\n  \n  // Raw JSON state for agent outputs\n  const [rawAgentOutputs, setRawAgentOutputs] = useState<{\n    eighthsAgent?: any;\n    sceneBreakdownAgent?: any;\n    departmentAgent?: any;\n    coordinatorAgent?: any;\n  }>({});\n  const [expandedRawSections, setExpandedRawSections] = useState<{\n    [key: string]: boolean;\n  }>({});\n\n  // Load script content on component mount\n  useEffect(() => {\n    if (selectedProject?.scriptContent) {\n      setOriginalScript(selectedProject.scriptContent);\n      setEditedScript(selectedProject.scriptContent);\n    }\n  }, [selectedProject]);\n\n  // Check for existing analysis results\n  useEffect(() => {\n    if (selectedProject) {\n      const storedResults = localStorage.getItem(`pdf_analysis_${selectedProject.id}`);\n      if (storedResults) {\n        try {\n          const results = JSON.parse(storedResults);\n          setPdfAnalysisResults(results);\n        } catch (error) {\n          console.error('Error loading stored analysis:', error);\n        }\n      }\n\n      const storedDepthResults = localStorage.getItem(`depth_analysis_${selectedProject.id}`);\n      if (storedDepthResults) {\n        try {\n          const results = JSON.parse(storedDepthResults);\n          setDepthAnalysisResults(results);\n        } catch (error) {\n          console.error('Error loading stored depth analysis:', error);\n        }\n      }\n    }\n  }, [selectedProject]);\n\n  // PDF Analysis functions using CJS API with fallback\n  const handlePdfUpload = async (event: Event) => {\n    const target = event.target as HTMLInputElement;\n    const file = target.files?.[0];\n    if (!file) return;\n\n    setIsPdfAnalyzing(true);\n    setPdfAnalysisError('');\n    setUploadedPdfName(file.name);\n\n    try {\n      console.log('\ud83d\udcc4 Starting PDF analysis with CJS API:', file.name);\n      \n      // Check for cached analysis first\n      const cached = cjsApiService.loadCachedAnalysis(file.name);\n      if (cached) {\n        console.log('\u26a1 Using cached analysis results');\n        const cacheResults = {\n          success: true,\n          data: cached,\n          source: cached.source || 'cache'\n        };\n        \n        setPdfAnalysisResults(cacheResults);\n        \n        if (selectedProject) {\n          localStorage.setItem(`pdf_analysis_${selectedProject.id}`, JSON.stringify(cacheResults));\n        }\n\n        toast.success(\"PDF Analysis Complete! (Cached)\", {\n          description: `Loaded ${cached.totalScenes || 0} scenes with ${cached.totalCharacters || 0} characters`,\n        });\n\n        triggerBackgroundProcessing(cached);\n        return;\n      }\n\n      // Use CJS API with browser fallback\n      const result = await cjsApiService.analyzePdfWithFallback(\n        file, \n        selectedProject?.id || 'unknown'\n      );\n      \n      console.log('\u2705 PDF analysis results:', result);\n      \n      if (result.success && result.data) {\n        const formattedResults = {\n          success: true,\n          data: result.data,\n          source: result.source\n        };\n        \n        setPdfAnalysisResults(formattedResults);\n        \n        // Store results in localStorage\n        if (selectedProject) {\n          localStorage.setItem(`pdf_analysis_${selectedProject.id}`, JSON.stringify(formattedResults));\n        }\n\n        const analysisSource = result.source === 'cjs' ? 'CJS API' : 'Browser Analysis';\n        toast.success(`PDF Analysis Complete! (${analysisSource})`, {\n          description: `Analyzed ${result.data.totalScenes || 0} scenes with ${result.data.totalCharacters || 0} characters`,\n        });\n\n        // Trigger background generation of schedule and budget\n        triggerBackgroundProcessing(result.data);\n      } else {\n        throw new Error(result.error || 'Analysis failed');\n      }\n    } catch (error) {\n      console.error('PDF analysis error:', error);\n      const errorMessage = error instanceof Error ? error.message : 'Failed to analyze PDF';\n      setPdfAnalysisError(errorMessage);\n      \n      toast.error(\"PDF Analysis Failed\", {\n        description: errorMessage,\n      });\n    } finally {\n      setIsPdfAnalyzing(false);\n    }\n  };\n\n  // Trigger background processing for schedule and budget\n  const triggerBackgroundProcessing = async (analysisData: any) => {\n    if (!selectedProject) return;\n\n    setBackgroundProcessStatus('Starting background processing...');\n    setBackgroundProcessComplete(false);\n\n    try {\n      // Generate schedule in background\n      setIsGeneratingSchedule(true);\n      setBackgroundProcessStatus('Generating production schedule...');\n\n      const scheduleInput: ScriptAnalysisInput = {\n        script: selectedProject.scriptContent,\n        scenes: analysisData.scenes || [],\n        characters: analysisData.characters || [],\n        locations: analysisData.locations || []\n      };\n\n      const scheduleResult = await generateProductionScheduleWithAI(scheduleInput);\n      \n      if (scheduleResult.success && scheduleResult.data) {\n        localStorage.setItem(`schedule_${selectedProject.id}`, JSON.stringify(scheduleResult.data));\n        setBackgroundProcessStatus('Schedule generated successfully. Generating budget...');\n      } else {\n        console.warn('Schedule generation failed:', scheduleResult.error);\n      }\n\n      // Generate budget in background\n      setIsGeneratingBudget(true);\n      setBackgroundProcessStatus('Generating production budget...');\n\n      const budgetInput = {\n        script: selectedProject.scriptContent,\n        analysisResults: analysisData,\n        scheduleResults: scheduleResult.data\n      };\n\n      const budgetResult = await generateBasicBudgetWithAI(budgetInput);\n      \n      if (budgetResult.success && budgetResult.data) {\n        localStorage.setItem(`budget_${selectedProject.id}`, JSON.stringify(budgetResult.data));\n        setBackgroundProcessStatus('Budget generated successfully!');\n      } else {\n        console.warn('Budget generation failed:', budgetResult.error);\n      }\n\n      setBackgroundProcessComplete(true);\n      toast.success(\"Background Processing Complete!\", {\n        description: \"Schedule and budget have been generated automatically\",\n      });\n\n    } catch (error) {\n      console.error('Background processing error:', error);\n      setBackgroundProcessStatus('Background processing completed with some errors');\n    } finally {\n      setIsGeneratingSchedule(false);\n      setIsGeneratingBudget(false);\n    }\n  };\n\n  // Depth Analysis using FILMUSTAGE service\n  const handleDepthAnalysis = async () => {\n    if (!selectedProject?.scriptContent) {\n      toast.error(\"No script content available for analysis\");\n      return;\n    }\n\n    setIsDepthAnalyzing(true);\n    setDepthAnalysisError('');\n    setDepthAnalysisProgress(0);\n    setCurrentDepthAgent('');\n\n    try {\n      console.log('\ud83e\udde0 Starting depth analysis with 4-agent pipeline');\n      \n      const result = await depthScriptAnalysisService.analyze(\n        selectedProject.scriptContent,\n        selectedProject.id,\n        (progress, agent) => {\n          setDepthAnalysisProgress(progress);\n          setCurrentDepthAgent(agent);\n        }\n      );\n\n      if (result.success && result.data) {\n        setDepthAnalysisResults(result.data);\n        setShowDepthResults(true);\n\n        // Store results\n        localStorage.setItem(`depth_analysis_${selectedProject.id}`, JSON.stringify(result.data));\n\n        toast.success(\"Depth Analysis Complete!\", {\n          description: \"4-agent pipeline analysis completed successfully\",\n        });\n      } else {\n        throw new Error(result.error || 'Depth analysis failed');\n      }\n    } catch (error) {\n      console.error('Depth analysis error:', error);\n      const errorMessage = error instanceof Error ? error.message : 'Depth analysis failed';\n      setDepthAnalysisError(errorMessage);\n      \n      toast.error(\"Depth Analysis Failed\", {\n        description: errorMessage,\n      });\n    } finally {\n      setIsDepthAnalyzing(false);\n      setDepthAnalysisProgress(0);\n      setCurrentDepthAgent('');\n    }\n  };\n\n  // Save script edits\n  const handleSaveScript = () => {\n    if (!selectedProject) return;\n\n    const updatedProject = {\n      ...selectedProject,\n      scriptContent: editedScript\n    };\n\n    // Update in localStorage\n    const existingProjects = JSON.parse(localStorage.getItem('filmustage_projects') || '[]');\n    const updatedProjects = existingProjects.map((p: ProjectData) => \n      p.id === selectedProject.id ? updatedProject : p\n    );\n    \n    localStorage.setItem('filmustage_projects', JSON.stringify(updatedProjects));\n    selectProject(updatedProject);\n    \n    setOriginalScript(editedScript);\n    setHasUnsavedChanges(false);\n    setIsEditMode(false);\n\n    toast.success(\"Script saved successfully!\");\n  };\n\n  // Reset script edits\n  const handleResetScript = () => {\n    setEditedScript(originalScript);\n    setHasUnsavedChanges(false);\n    setIsEditMode(false);\n  };\n\n  // Export functions\n  const exportScriptAnalysis = () => {\n    if (!pdfAnalysisResults) return;\n\n    const exportData = {\n      project: selectedProject?.name,\n      timestamp: new Date().toISOString(),\n      analysis: pdfAnalysisResults.data,\n      scenes: pdfAnalysisResults.data?.scenes?.length || 0,\n      characters: pdfAnalysisResults.data?.characters?.length || 0\n    };\n\n    const blob = new Blob([JSON.stringify(exportData, null, 2)], { type: 'application/json' });\n    const url = URL.createObjectURL(blob);\n    const a = document.createElement('a');\n    a.href = url;\n    a.download = `script-analysis-${selectedProject?.name || 'project'}.json`;\n    document.body.appendChild(a);\n    a.click();\n    document.body.removeChild(a);\n    URL.revokeObjectURL(url);\n\n    toast.success(\"Analysis exported successfully!\");\n  };\n\n  // Script editing handlers\n  const handleScriptChange = (value: string) => {\n    setEditedScript(value);\n    setHasUnsavedChanges(value !== originalScript);\n  };\n\n  if (!selectedProject) {\n    return (\n      <div className=\"container mx-auto px-4 py-8\">\n        <Card>\n          <CardContent className=\"flex flex-col items-center justify-center h-64 text-center\">\n            <FileText className=\"h-12 w-12 text-muted-foreground mb-4\" />\n            <h3 className=\"text-xl font-medium mb-2\">No Project Selected</h3>\n            <p className=\"text-muted-foreground mb-4\">Select a project to analyze its script</p>\n            <Button asChild>\n              <a href=\"/dashboard/admin/upload-script\">Create Project</a>\n            </Button>\n          </CardContent>\n        </Card>\n      </div>\n    );\n  }\n\n  return (\n    <div className=\"container mx-auto px-4 py-8\">\n      <div className=\"max-w-7xl mx-auto\">\n        {/* Header */}\n        <div className=\"flex items-center justify-between mb-8\">\n          <div>\n            <h1 className=\"text-3xl font-bold\">\ud83c\udfac Script Analysis</h1>\n            <p className=\"text-muted-foreground mt-2\">\n              Project: {selectedProject.name}\n            </p>\n          </div>\n          <div className=\"flex items-center gap-3\">\n            {pdfAnalysisResults && (\n              <Button variant=\"outline\" onClick={exportScriptAnalysis}>\n                <Download className=\"w-4 h-4 mr-2\" />\n                Export Analysis\n              </Button>\n            )}\n            <Button asChild>\n              <a href=\"/dashboard/admin/upload-script\">\n                <Upload className=\"w-4 h-4 mr-2\" />\n                New Project\n              </a>\n            </Button>\n          </div>\n        </div>\n\n        {/* Tab Navigation */}\n        <div className=\"border-b border-gray-200 mb-8\">\n          <nav className=\"-mb-px flex space-x-8\">\n            <button\n              onClick={() => setActiveTab('edit')}\n              className={`py-2 px-1 border-b-2 font-medium text-sm ${\n                activeTab === 'edit'\n                  ? 'border-blue-500 text-blue-600'\n                  : 'border-transparent text-gray-500 hover:text-gray-700 hover:border-gray-300'\n              }`}\n            >\n              <FileEdit className=\"w-4 h-4 mr-2 inline\" />\n              Script Editor\n            </button>\n            <button\n              onClick={() => setActiveTab('pdf')}\n              className={`py-2 px-1 border-b-2 font-medium text-sm ${\n                activeTab === 'pdf'\n                  ? 'border-blue-500 text-blue-600'\n                  : 'border-transparent text-gray-500 hover:text-gray-700 hover:border-gray-300'\n              }`}\n            >\n              <FileText className=\"w-4 h-4 mr-2 inline\" />\n              PDF Analysis\n            </button>\n            <button\n              onClick={() => setActiveTab('depth')}\n              className={`py-2 px-1 border-b-2 font-medium text-sm ${\n                activeTab === 'depth'\n                  ? 'border-blue-500 text-blue-600'\n                  : 'border-transparent text-gray-500 hover:text-gray-700 hover:border-gray-300'\n              }`}\n            >\n              <Brain className=\"w-4 h-4 mr-2 inline\" />\n              Depth Analysis\n            </button>\n          </nav>\n        </div>\n\n        {/* Tab Content */}\n        {activeTab === 'edit' && (\n          <div className=\"space-y-6\">\n            <Card>\n              <CardHeader>\n                <div className=\"flex items-center justify-between\">\n                  <CardTitle>Script Editor</CardTitle>\n                  <div className=\"flex items-center gap-2\">\n                    {hasUnsavedChanges && (\n                      <Badge variant=\"outline\" className=\"text-orange-600\">\n                        <AlertCircle className=\"w-3 h-3 mr-1\" />\n                        Unsaved Changes\n                      </Badge>\n                    )}\n                    <Button\n                      variant=\"outline\"\n                      size=\"sm\"\n                      onClick={() => setIsEditMode(!isEditMode)}\n                    >\n                      {isEditMode ? <Eye className=\"w-4 h-4 mr-2\" /> : <Edit3 className=\"w-4 h-4 mr-2\" />}\n                      {isEditMode ? 'Preview' : 'Edit'}\n                    </Button>\n                  </div>\n                </div>\n              </CardHeader>\n              <CardContent>\n                {isEditMode ? (\n                  <div className=\"space-y-4\">\n                    <Textarea\n                      value={editedScript}\n                      onChange={(e) => handleScriptChange(e.target.value)}\n                      className=\"min-h-[500px] font-mono text-sm\"\n                      placeholder=\"Enter your script content here...\"\n                    />\n                    <div className=\"flex items-center gap-2\">\n                      <Button onClick={handleSaveScript} disabled={!hasUnsavedChanges}>\n                        <Save className=\"w-4 h-4 mr-2\" />\n                        Save Changes\n                      </Button>\n                      <Button variant=\"outline\" onClick={handleResetScript} disabled={!hasUnsavedChanges}>\n                        <RotateCcw className=\"w-4 h-4 mr-2\" />\n                        Reset\n                      </Button>\n                    </div>\n                  </div>\n                ) : (\n                  <div className=\"bg-gray-50 p-4 rounded-lg\">\n                    <pre className=\"whitespace-pre-wrap font-mono text-sm\">\n                      {editedScript || 'No script content available'}\n                    </pre>\n                  </div>\n                )}\n              </CardContent>\n            </Card>\n          </div>\n        )}\n\n        {activeTab === 'pdf' && (\n          <div className=\"space-y-6\">\n            {!pdfAnalysisResults && (\n              <Card>\n                <CardHeader>\n                  <CardTitle>PDF Script Analysis</CardTitle>\n                </CardHeader>\n                <CardContent>\n                  <div className=\"text-center py-8\">\n                    <Upload className=\"w-12 h-12 text-muted-foreground mx-auto mb-4\" />\n                    <h3 className=\"text-lg font-medium mb-2\">Upload Script PDF</h3>\n                    <p className=\"text-muted-foreground mb-4\">\n                      Upload a PDF script file for comprehensive AI analysis\n                    </p>\n                    <input\n                      type=\"file\"\n                      accept=\".pdf\"\n                      onChange={(e) => handlePdfUpload(e as any)}\n                      className=\"hidden\"\n                      id=\"pdf-upload\"\n                    />\n                    <Button\n                      onClick={() => document.getElementById('pdf-upload')?.click()}\n                      disabled={isPdfAnalyzing}\n                    >\n                      {isPdfAnalyzing ? (\n                        <>\n                          <Loader2 className=\"w-4 h-4 mr-2 animate-spin\" />\n                          Analyzing...\n                        </>\n                      ) : (\n                        <>\n                          <Upload className=\"w-4 h-4 mr-2\" />\n                          Choose PDF File\n                        </>\n                      )}\n                    </Button>\n                  </div>\n                </CardContent>\n              </Card>\n            )}\n\n            {isPdfAnalyzing && (\n              <Card>\n                <CardContent className=\"p-6\">\n                  <div className=\"text-center\">\n                    <Loader2 className=\"w-8 h-8 animate-spin mx-auto mb-4\" />\n                    <h3 className=\"text-lg font-medium mb-2\">Analyzing PDF Script</h3>\n                    <p className=\"text-muted-foreground\">\n                      {uploadedPdfName && `Processing: ${uploadedPdfName}`}\n                    </p>\n                  </div>\n                </CardContent>\n              </Card>\n            )}\n\n            {pdfAnalysisError && (\n              <Card className=\"border-red-200\">\n                <CardContent className=\"p-6\">\n                  <div className=\"text-center text-red-600\">\n                    <AlertCircle className=\"w-8 h-8 mx-auto mb-4\" />\n                    <h3 className=\"text-lg font-medium mb-2\">Analysis Failed</h3>\n                    <p>{pdfAnalysisError}</p>\n                  </div>\n                </CardContent>\n              </Card>\n            )}\n\n            {pdfAnalysisResults && (\n              <div className=\"space-y-6\">\n                <Card>\n                  <CardHeader>\n                    <CardTitle className=\"flex items-center gap-2\">\n                      <CheckCircle className=\"w-5 h-5 text-green-600\" />\n                      Analysis Complete\n                    </CardTitle>\n                  </CardHeader>\n                  <CardContent>\n                    <div className=\"grid grid-cols-2 md:grid-cols-4 gap-4\">\n                      <div className=\"text-center\">\n                        <div className=\"text-2xl font-bold text-blue-600\">\n                          {pdfAnalysisResults.data?.totalScenes || pdfAnalysisResults.data?.scenes?.length || 0}\n                        </div>\n                        <div className=\"text-sm text-muted-foreground\">Scenes</div>\n                      </div>\n                      <div className=\"text-center\">\n                        <div className=\"text-2xl font-bold text-green-600\">\n                          {pdfAnalysisResults.data?.totalCharacters || pdfAnalysisResults.data?.characters?.length || 0}\n                        </div>\n                        <div className=\"text-sm text-muted-foreground\">Characters</div>\n                      </div>\n                      <div className=\"text-center\">\n                        <div className=\"text-2xl font-bold text-orange-600\">\n                          {pdfAnalysisResults.data?.totalDialogues || pdfAnalysisResults.data?.dialogues?.length || 0}\n                        </div>\n                        <div className=\"text-sm text-muted-foreground\">Dialogues</div>\n                      </div>\n                      <div className=\"text-center\">\n                        <div className=\"text-2xl font-bold text-purple-600\">\n                          {pdfAnalysisResults.data?.interactions?.length || 0}\n                        </div>\n                        <div className=\"text-sm text-muted-foreground\">Interactions</div>\n                      </div>\n                    </div>\n                    \n                    {pdfAnalysisResults.source && (\n                      <div className=\"mt-4 text-center\">\n                        <Badge variant={pdfAnalysisResults.source === 'cjs' ? 'default' : 'secondary'}>\n                          Analysis Source: {pdfAnalysisResults.source === 'cjs' ? 'CJS API (Fast)' : 'Browser (Fallback)'}\n                        </Badge>\n                      </div>\n                    )}\n                  </CardContent>\n                </Card>\n\n                {/* Scene Breakdown */}\n                {pdfAnalysisResults.data?.scenes && (\n                  <Card>\n                    <CardHeader>\n                      <CardTitle>Scene Breakdown</CardTitle>\n                    </CardHeader>\n                    <CardContent>\n                      <div className=\"space-y-4\">\n                        {pdfAnalysisResults.data.scenes.slice(0, 5).map((scene: any, index: number) => (\n                          <div key={index} className=\"border-l-4 border-blue-500 pl-4\">\n                            <h4 className=\"font-medium\">{scene.Scene_Names || scene.header || `Scene ${index + 1}`}</h4>\n                            <div className=\"flex flex-wrap gap-2 mt-2\">\n                              {scene.Scene_Characters?.map((char: string, i: number) => (\n                                <CategoryBadge key={i} variant=\"cast\">{char}</CategoryBadge>\n                              )) || scene.characters?.map((char: string, i: number) => (\n                                <CategoryBadge key={i} variant=\"cast\">{char}</CategoryBadge>\n                              ))}\n                            </div>\n                            {(scene.Scene_action || scene.summary) && (\n                              <p className=\"text-sm text-muted-foreground mt-2 line-clamp-3\">\n                                {scene.Scene_action || scene.summary}\n                              </p>\n                            )}\n                            {scene.Scene_Dialogue && scene.Scene_Dialogue.length > 0 && (\n                              <div className=\"mt-2\">\n                                <span className=\"text-xs font-medium text-gray-600\">Dialogues: </span>\n                                <span className=\"text-xs text-gray-500\">\n                                  {scene.Scene_Dialogue.slice(0, 2).join(', ')}\n                                  {scene.Scene_Dialogue.length > 2 && '...'}\n                                </span>\n                              </div>\n                            )}\n                          </div>\n                        ))}\n                        {pdfAnalysisResults.data.scenes.length > 5 && (\n                          <p className=\"text-sm text-muted-foreground text-center mt-4\">\n                            And {pdfAnalysisResults.data.scenes.length - 5} more scenes...\n                          </p>\n                        )}\n                      </div>\n                    </CardContent>\n                  </Card>\n                )}\n\n                {/* Characters List */}\n                {pdfAnalysisResults.data?.characters && (\n                  <Card>\n                    <CardHeader>\n                      <CardTitle>Characters</CardTitle>\n                    </CardHeader>\n                    <CardContent>\n                      <div className=\"flex flex-wrap gap-2\">\n                        {pdfAnalysisResults.data.characters.slice(0, 20).map((character: string, index: number) => (\n                          <CategoryBadge key={index} variant=\"cast\">{character}</CategoryBadge>\n                        ))}\n                        {pdfAnalysisResults.data.characters.length > 20 && (\n                          <span className=\"text-sm text-muted-foreground\">\n                            +{pdfAnalysisResults.data.characters.length - 20} more\n                          </span>\n                        )}\n                      </div>\n                    </CardContent>\n                  </Card>\n                )}\n\n                {/* Character Interactions */}\n                {pdfAnalysisResults.data?.interactions && pdfAnalysisResults.data.interactions.length > 0 && (\n                  <Card>\n                    <CardHeader>\n                      <CardTitle>Character Interactions</CardTitle>\n                    </CardHeader>\n                    <CardContent>\n                      <div className=\"space-y-2\">\n                        {pdfAnalysisResults.data.interactions.slice(0, 10).map((interaction: any, index: number) => (\n                          <div key={index} className=\"flex items-center justify-between\">\n                            <span className=\"text-sm\">{interaction.pair}</span>\n                            <Badge variant=\"outline\">{interaction.count} scenes</Badge>\n                          </div>\n                        ))}\n                        {pdfAnalysisResults.data.interactions.length > 10 && (\n                          <p className=\"text-sm text-muted-foreground text-center mt-4\">\n                            And {pdfAnalysisResults.data.interactions.length - 10} more interactions...\n                          </p>\n                        )}\n                      </div>\n                    </CardContent>\n                  </Card>\n                )}\n              </div>\n            )}\n\n            {/* Background Processing Status */}\n            {(isGeneratingSchedule || isGeneratingBudget || backgroundProcessStatus) && (\n              <Card className=\"border-blue-200\">\n                <CardHeader>\n                  <CardTitle className=\"flex items-center gap-2\">\n                    <Loader2 className=\"w-5 h-5 animate-spin text-blue-600\" />\n                    Background Processing\n                  </CardTitle>\n                </CardHeader>\n                <CardContent>\n                  <p className=\"text-sm text-muted-foreground mb-4\">\n                    {backgroundProcessStatus}\n                  </p>\n                  <div className=\"flex items-center gap-4\">\n                    <div className=\"flex items-center gap-2\">\n                      {isGeneratingSchedule ? (\n                        <Loader2 className=\"w-4 h-4 animate-spin text-blue-600\" />\n                      ) : (\n                        <CheckCircle className=\"w-4 h-4 text-green-600\" />\n                      )}\n                      <span className=\"text-sm\">Schedule Generation</span>\n                    </div>\n                    <div className=\"flex items-center gap-2\">\n                      {isGeneratingBudget ? (\n                        <Loader2 className=\"w-4 h-4 animate-spin text-blue-600\" />\n                      ) : backgroundProcessComplete ? (\n                        <CheckCircle className=\"w-4 h-4 text-green-600\" />\n                      ) : (\n                        <Clock className=\"w-4 h-4 text-gray-400\" />\n                      )}\n                      <span className=\"text-sm\">Budget Generation</span>\n                    </div>\n                  </div>\n                </CardContent>\n              </Card>\n            )}\n          </div>\n        )}\n\n        {activeTab === 'depth' && (\n          <div className=\"space-y-6\">\n            <Card>\n              <CardHeader>\n                <CardTitle>Depth Analysis</CardTitle>\n                <p className=\"text-sm text-muted-foreground\">\n                  Advanced 4-agent pipeline analysis for comprehensive script breakdown\n                </p>\n              </CardHeader>\n              <CardContent>\n                <div className=\"space-y-4\">\n                  <Button\n                    onClick={handleDepthAnalysis}\n                    disabled={isDepthAnalyzing || !selectedProject?.scriptContent}\n                    className=\"w-full\"\n                  >\n                    {isDepthAnalyzing ? (\n                      <>\n                        <Loader2 className=\"w-4 h-4 mr-2 animate-spin\" />\n                        Running Depth Analysis... ({depthAnalysisProgress}%)\n                      </>\n                    ) : (\n                      <>\n                        <Brain className=\"w-4 h-4 mr-2\" />\n                        Start Depth Analysis\n                      </>\n                    )}\n                  </Button>\n\n                  {isDepthAnalyzing && (\n                    <div className=\"space-y-2\">\n                      <div className=\"flex justify-between text-sm\">\n                        <span>Progress: {currentDepthAgent}</span>\n                        <span>{depthAnalysisProgress}%</span>\n                      </div>\n                      <div className=\"w-full bg-gray-200 rounded-full h-2\">\n                        <div\n                          className=\"bg-blue-600 h-2 rounded-full transition-all duration-300\"\n                          style={{ width: `${depthAnalysisProgress}%` }}\n                        ></div>\n                      </div>\n                    </div>\n                  )}\n\n                  {depthAnalysisError && (\n                    <div className=\"text-red-600 text-sm\">\n                      <AlertCircle className=\"w-4 h-4 mr-2 inline\" />\n                      {depthAnalysisError}\n                    </div>\n                  )}\n                </div>\n              </CardContent>\n            </Card>\n\n            {depthAnalysisResults && showDepthResults && (\n              <Card>\n                <CardHeader>\n                  <CardTitle className=\"flex items-center gap-2\">\n                    <CheckCircle className=\"w-5 h-5 text-green-600\" />\n                    Depth Analysis Results\n                  </CardTitle>\n                </CardHeader>\n                <CardContent>\n                  <div className=\"space-y-4\">\n                    <div className=\"grid grid-cols-2 md:grid-cols-4 gap-4\">\n                      <div className=\"text-center\">\n                        <div className=\"text-2xl font-bold text-blue-600\">\n                          {depthAnalysisResults.totalScenes || 0}\n                        </div>\n                        <div className=\"text-sm text-muted-foreground\">Scenes Analyzed</div>\n                      </div>\n                      <div className=\"text-center\">\n                        <div className=\"text-2xl font-bold text-green-600\">\n                          {depthAnalysisResults.totalCharacters || 0}\n                        </div>\n                        <div className=\"text-sm text-muted-foreground\">Characters</div>\n                      </div>\n                      <div className=\"text-center\">\n                        <div className=\"text-2xl font-bold text-orange-600\">\n                          {depthAnalysisResults.totalLocations || 0}\n                        </div>\n                        <div className=\"text-sm text-muted-foreground\">Locations</div>\n                      </div>\n                      <div className=\"text-center\">\n                        <div className=\"text-2xl font-bold text-purple-600\">\n                          4\n                        </div>\n                        <div className=\"text-sm text-muted-foreground\">AI Agents</div>\n                      </div>\n                    </div>\n\n                    {depthAnalysisResults.summary && (\n                      <div className=\"bg-gray-50 p-4 rounded-lg\">\n                        <h4 className=\"font-medium mb-2\">Analysis Summary</h4>\n                        <p className=\"text-sm text-muted-foreground\">\n                          {depthAnalysisResults.summary}\n                        </p>\n                      </div>\n                    )}\n                  </div>\n                </CardContent>\n              </Card>\n            )}\n          </div>\n        )}\n      </div>\n    </div>\n  );\n}",
/Users/varunisrani/Downloads/filmustage-ui-kit-main/think.ai/logs/post_tool_use.json:11368:      "originalFile": "\"use client\"\n\nimport { useState, useEffect } from 'react';\nimport { Button } from '@/components/ui/button';\nimport { Textarea } from '@/components/ui/textarea';\nimport { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';\nimport { Badge } from '@/components/ui/badge';\nimport { CategoryBadge } from '@/components/ui/CategoryBadge';\nimport { useSelectedProject } from '@/hooks/useSelectedProject';\nimport { toast } from 'sonner';\nimport { \n  Search, \n  FileText, \n  Share2, \n  Download, \n  Upload, \n  Edit3, \n  Save, \n  RotateCcw, \n  Eye, \n  FileEdit, \n  AlertCircle, \n  Loader2, \n  CheckCircle, \n  Brain, \n  BarChart3, \n  Clock, \n  Users, \n  MapPin, \n  DollarSign, \n  AlertTriangle, \n  Code, \n  ChevronDown, \n  ChevronRight, \n  Copy, \n  Download as DownloadIcon \n} from 'lucide-react';\nimport { ProjectData } from '@/lib/types';\nimport { generateProductionScheduleWithAI, ScriptAnalysisInput } from '@/lib/services/schedulingGeneratorService';\nimport { generateBasicBudgetWithAI } from '@/lib/services/basicBudgetGeneratorService';\nimport { depthScriptAnalysisService, CoordinatorOutput } from '@/lib/services/depthScriptAnalysisService';\nimport { cjsApiService } from '@/lib/services/cjsApiService';\n\nconsole.log('\ud83d\udcc4 Enhanced ScriptPage configured for comprehensive analysis');\n\nexport default function ScriptAnalysisPage() {\n  const { selectedProject, selectProject } = useSelectedProject();\n  const [activeTab, setActiveTab] = useState<'edit' | 'pdf' | 'depth'>('pdf');\n  const [searchTerm, setSearchTerm] = useState('');\n  const [selectedScene, setSelectedScene] = useState(1);\n  const [notes, setNotes] = useState('');\n  \n  // Script editing state\n  const [editedScript, setEditedScript] = useState<string>('');\n  const [originalScript, setOriginalScript] = useState<string>('');\n  const [hasUnsavedChanges, setHasUnsavedChanges] = useState(false);\n  const [isEditMode, setIsEditMode] = useState(false);\n  const [currentPage, setCurrentPage] = useState(1);\n  const [linesPerPage] = useState(50);\n\n  // PDF analysis state\n  const [pdfAnalysisResults, setPdfAnalysisResults] = useState<any | null>(null);\n  const [isPdfAnalyzing, setIsPdfAnalyzing] = useState(false);\n  const [pdfAnalysisError, setPdfAnalysisError] = useState('');\n  const [uploadedPdfName, setUploadedPdfName] = useState('');\n  const [showRawResponse, setShowRawResponse] = useState(false);\n  const [showAllScenes, setShowAllScenes] = useState(false);\n\n  // Background processing state\n  const [isGeneratingSchedule, setIsGeneratingSchedule] = useState(false);\n  const [isGeneratingBudget, setIsGeneratingBudget] = useState(false);\n  const [backgroundProcessStatus, setBackgroundProcessStatus] = useState('');\n  const [backgroundProcessComplete, setBackgroundProcessComplete] = useState(false);\n\n  // Depth Analysis state\n  const [depthAnalysisResults, setDepthAnalysisResults] = useState<CoordinatorOutput | null>(null);\n  const [isDepthAnalyzing, setIsDepthAnalyzing] = useState(false);\n  const [depthAnalysisError, setDepthAnalysisError] = useState('');\n  const [depthAnalysisProgress, setDepthAnalysisProgress] = useState(0);\n  const [currentDepthAgent, setCurrentDepthAgent] = useState('');\n  const [showDepthResults, setShowDepthResults] = useState(false);\n  \n  // Raw JSON state for agent outputs\n  const [rawAgentOutputs, setRawAgentOutputs] = useState<{\n    eighthsAgent?: any;\n    sceneBreakdownAgent?: any;\n    departmentAgent?: any;\n    coordinatorAgent?: any;\n  }>({});\n  const [expandedRawSections, setExpandedRawSections] = useState<{\n    [key: string]: boolean;\n  }>({});\n\n  // Load script content on component mount\n  useEffect(() => {\n    if (selectedProject?.scriptContent) {\n      setOriginalScript(selectedProject.scriptContent);\n      setEditedScript(selectedProject.scriptContent);\n    }\n  }, [selectedProject]);\n\n  // Check for existing analysis results\n  useEffect(() => {\n    if (selectedProject) {\n      const storedResults = localStorage.getItem(`pdf_analysis_${selectedProject.id}`);\n      if (storedResults) {\n        try {\n          const results = JSON.parse(storedResults);\n          setPdfAnalysisResults(results);\n        } catch (error) {\n          console.error('Error loading stored analysis:', error);\n        }\n      }\n\n      const storedDepthResults = localStorage.getItem(`depth_analysis_${selectedProject.id}`);\n      if (storedDepthResults) {\n        try {\n          const results = JSON.parse(storedDepthResults);\n          setDepthAnalysisResults(results);\n        } catch (error) {\n          console.error('Error loading stored depth analysis:', error);\n        }\n      }\n    }\n  }, [selectedProject]);\n\n  // PDF Analysis functions using CJS API with fallback\n  const handlePdfUpload = async (event: Event) => {\n    const target = event.target as HTMLInputElement;\n    const file = target.files?.[0];\n    if (!file) return;\n\n    setIsPdfAnalyzing(true);\n    setPdfAnalysisError('');\n    setUploadedPdfName(file.name);\n\n    try {\n      console.log('\ud83d\udcc4 Starting PDF analysis with CJS API:', file.name);\n      \n      // Check for cached analysis first\n      const cached = cjsApiService.loadCachedAnalysis(file.name);\n      if (cached) {\n        console.log('\u26a1 Using cached analysis results');\n        const cacheResults = {\n          success: true,\n          data: cached,\n          source: cached.source || 'cache'\n        };\n        \n        setPdfAnalysisResults(cacheResults);\n        \n        if (selectedProject) {\n          localStorage.setItem(`pdf_analysis_${selectedProject.id}`, JSON.stringify(cacheResults));\n        }\n\n        toast.success(\"PDF Analysis Complete! (Cached)\", {\n          description: `Loaded ${cached.totalScenes || 0} scenes with ${cached.totalCharacters || 0} characters`,\n        });\n\n        triggerBackgroundProcessing(cached);\n        return;\n      }\n\n      // Use CJS API with browser fallback\n      const result = await cjsApiService.analyzePdfWithFallback(\n        file, \n        selectedProject?.id || 'unknown'\n      );\n      \n      console.log('\u2705 PDF analysis results:', result);\n      \n      if (result.success && result.data) {\n        const formattedResults = {\n          success: true,\n          data: result.data,\n          source: result.source\n        };\n        \n        setPdfAnalysisResults(formattedResults);\n        \n        // Store results in localStorage\n        if (selectedProject) {\n          localStorage.setItem(`pdf_analysis_${selectedProject.id}`, JSON.stringify(formattedResults));\n        }\n\n        const analysisSource = result.source === 'cjs' ? 'CJS API' : 'Browser Analysis';\n        toast.success(`PDF Analysis Complete! (${analysisSource})`, {\n          description: `Analyzed ${result.data.totalScenes || 0} scenes with ${result.data.totalCharacters || 0} characters`,\n        });\n\n        // Trigger background generation of schedule and budget\n        triggerBackgroundProcessing(result.data);\n      } else {\n        throw new Error(result.error || 'Analysis failed');\n      }\n    } catch (error) {\n      console.error('PDF analysis error:', error);\n      const errorMessage = error instanceof Error ? error.message : 'Failed to analyze PDF';\n      setPdfAnalysisError(errorMessage);\n      \n      toast.error(\"PDF Analysis Failed\", {\n        description: errorMessage,\n      });\n    } finally {\n      setIsPdfAnalyzing(false);\n    }\n  };\n\n  // Trigger background processing for schedule and budget\n  const triggerBackgroundProcessing = async (analysisData: any) => {\n    if (!selectedProject) return;\n\n    setBackgroundProcessStatus('Starting background processing...');\n    setBackgroundProcessComplete(false);\n\n    try {\n      // Generate schedule in background\n      setIsGeneratingSchedule(true);\n      setBackgroundProcessStatus('Generating production schedule...');\n\n      const scheduleInput: ScriptAnalysisInput = {\n        script: selectedProject.scriptContent,\n        scenes: analysisData.scenes || [],\n        characters: analysisData.characters || [],\n        locations: analysisData.locations || []\n      };\n\n      const scheduleResult = await generateProductionScheduleWithAI(scheduleInput);\n      \n      if (scheduleResult.success && scheduleResult.data) {\n        localStorage.setItem(`schedule_${selectedProject.id}`, JSON.stringify(scheduleResult.data));\n        setBackgroundProcessStatus('Schedule generated successfully. Generating budget...');\n      } else {\n        console.warn('Schedule generation failed:', scheduleResult.error);\n      }\n\n      // Generate budget in background\n      setIsGeneratingBudget(true);\n      setBackgroundProcessStatus('Generating production budget...');\n\n      const budgetInput = {\n        script: selectedProject.scriptContent,\n        analysisResults: analysisData,\n        scheduleResults: scheduleResult.data\n      };\n\n      const budgetResult = await generateBasicBudgetWithAI(budgetInput);\n      \n      if (budgetResult.success && budgetResult.data) {\n        localStorage.setItem(`budget_${selectedProject.id}`, JSON.stringify(budgetResult.data));\n        setBackgroundProcessStatus('Budget generated successfully!');\n      } else {\n        console.warn('Budget generation failed:', budgetResult.error);\n      }\n\n      setBackgroundProcessComplete(true);\n      toast.success(\"Background Processing Complete!\", {\n        description: \"Schedule and budget have been generated automatically\",\n      });\n\n    } catch (error) {\n      console.error('Background processing error:', error);\n      setBackgroundProcessStatus('Background processing completed with some errors');\n    } finally {\n      setIsGeneratingSchedule(false);\n      setIsGeneratingBudget(false);\n    }\n  };\n\n  // Depth Analysis using FILMUSTAGE service\n  const handleDepthAnalysis = async () => {\n    if (!selectedProject?.scriptContent) {\n      toast.error(\"No script content available for analysis\");\n      return;\n    }\n\n    setIsDepthAnalyzing(true);\n    setDepthAnalysisError('');\n    setDepthAnalysisProgress(0);\n    setCurrentDepthAgent('');\n\n    try {\n      console.log('\ud83e\udde0 Starting depth analysis with 4-agent pipeline');\n      \n      const result = await depthScriptAnalysisService.analyze(\n        selectedProject.scriptContent,\n        selectedProject.id,\n        (progress, agent) => {\n          setDepthAnalysisProgress(progress);\n          setCurrentDepthAgent(agent);\n        }\n      );\n\n      if (result.success && result.data) {\n        setDepthAnalysisResults(result.data);\n        setShowDepthResults(true);\n\n        // Store results\n        localStorage.setItem(`depth_analysis_${selectedProject.id}`, JSON.stringify(result.data));\n\n        toast.success(\"Depth Analysis Complete!\", {\n          description: \"4-agent pipeline analysis completed successfully\",\n        });\n      } else {\n        throw new Error(result.error || 'Depth analysis failed');\n      }\n    } catch (error) {\n      console.error('Depth analysis error:', error);\n      const errorMessage = error instanceof Error ? error.message : 'Depth analysis failed';\n      setDepthAnalysisError(errorMessage);\n      \n      toast.error(\"Depth Analysis Failed\", {\n        description: errorMessage,\n      });\n    } finally {\n      setIsDepthAnalyzing(false);\n      setDepthAnalysisProgress(0);\n      setCurrentDepthAgent('');\n    }\n  };\n\n  // Save script edits\n  const handleSaveScript = () => {\n    if (!selectedProject) return;\n\n    const updatedProject = {\n      ...selectedProject,\n      scriptContent: editedScript\n    };\n\n    // Update in localStorage\n    const existingProjects = JSON.parse(localStorage.getItem('filmustage_projects') || '[]');\n    const updatedProjects = existingProjects.map((p: ProjectData) => \n      p.id === selectedProject.id ? updatedProject : p\n    );\n    \n    localStorage.setItem('filmustage_projects', JSON.stringify(updatedProjects));\n    selectProject(updatedProject);\n    \n    setOriginalScript(editedScript);\n    setHasUnsavedChanges(false);\n    setIsEditMode(false);\n\n    toast.success(\"Script saved successfully!\");\n  };\n\n  // Reset script edits\n  const handleResetScript = () => {\n    setEditedScript(originalScript);\n    setHasUnsavedChanges(false);\n    setIsEditMode(false);\n  };\n\n  // Export functions\n  const exportScriptAnalysis = () => {\n    if (!pdfAnalysisResults) return;\n\n    const exportData = {\n      project: selectedProject?.name,\n      timestamp: new Date().toISOString(),\n      analysis: pdfAnalysisResults.data,\n      scenes: pdfAnalysisResults.data?.scenes?.length || 0,\n      characters: pdfAnalysisResults.data?.characters?.length || 0\n    };\n\n    const blob = new Blob([JSON.stringify(exportData, null, 2)], { type: 'application/json' });\n    const url = URL.createObjectURL(blob);\n    const a = document.createElement('a');\n    a.href = url;\n    a.download = `script-analysis-${selectedProject?.name || 'project'}.json`;\n    document.body.appendChild(a);\n    a.click();\n    document.body.removeChild(a);\n    URL.revokeObjectURL(url);\n\n    toast.success(\"Analysis exported successfully!\");\n  };\n\n  // Script editing handlers\n  const handleScriptChange = (value: string) => {\n    setEditedScript(value);\n    setHasUnsavedChanges(value !== originalScript);\n  };\n\n  if (!selectedProject) {\n    return (\n      <div className=\"container mx-auto px-4 py-8\">\n        <Card>\n          <CardContent className=\"flex flex-col items-center justify-center h-64 text-center\">\n            <FileText className=\"h-12 w-12 text-muted-foreground mb-4\" />\n            <h3 className=\"text-xl font-medium mb-2\">No Project Selected</h3>\n            <p className=\"text-muted-foreground mb-4\">Select a project to analyze its script</p>\n            <Button asChild>\n              <a href=\"/dashboard/admin/upload-script\">Create Project</a>\n            </Button>\n          </CardContent>\n        </Card>\n      </div>\n    );\n  }\n\n  return (\n    <div className=\"container mx-auto px-4 py-8\">\n      <div className=\"max-w-7xl mx-auto\">\n        {/* Header */}\n        <div className=\"flex items-center justify-between mb-8\">\n          <div>\n            <h1 className=\"text-3xl font-bold\">\ud83c\udfac Script Analysis</h1>\n            <p className=\"text-muted-foreground mt-2\">\n              Project: {selectedProject.name}\n            </p>\n          </div>\n          <div className=\"flex items-center gap-3\">\n            {pdfAnalysisResults && (\n              <Button variant=\"outline\" onClick={exportScriptAnalysis}>\n                <Download className=\"w-4 h-4 mr-2\" />\n                Export Analysis\n              </Button>\n            )}\n            <Button asChild>\n              <a href=\"/dashboard/admin/upload-script\">\n                <Upload className=\"w-4 h-4 mr-2\" />\n                New Project\n              </a>\n            </Button>\n          </div>\n        </div>\n\n        {/* Tab Navigation */}\n        <div className=\"border-b border-gray-200 mb-8\">\n          <nav className=\"-mb-px flex space-x-8\">\n            <button\n              onClick={() => setActiveTab('edit')}\n              className={`py-2 px-1 border-b-2 font-medium text-sm ${\n                activeTab === 'edit'\n                  ? 'border-blue-500 text-blue-600'\n                  : 'border-transparent text-gray-500 hover:text-gray-700 hover:border-gray-300'\n              }`}\n            >\n              <FileEdit className=\"w-4 h-4 mr-2 inline\" />\n              Script Editor\n            </button>\n            <button\n              onClick={() => setActiveTab('pdf')}\n              className={`py-2 px-1 border-b-2 font-medium text-sm ${\n                activeTab === 'pdf'\n                  ? 'border-blue-500 text-blue-600'\n                  : 'border-transparent text-gray-500 hover:text-gray-700 hover:border-gray-300'\n              }`}\n            >\n              <FileText className=\"w-4 h-4 mr-2 inline\" />\n              PDF Analysis\n            </button>\n            <button\n              onClick={() => setActiveTab('depth')}\n              className={`py-2 px-1 border-b-2 font-medium text-sm ${\n                activeTab === 'depth'\n                  ? 'border-blue-500 text-blue-600'\n                  : 'border-transparent text-gray-500 hover:text-gray-700 hover:border-gray-300'\n              }`}\n            >\n              <Brain className=\"w-4 h-4 mr-2 inline\" />\n              Depth Analysis\n            </button>\n          </nav>\n        </div>\n\n        {/* Tab Content */}\n        {activeTab === 'edit' && (\n          <div className=\"space-y-6\">\n            <Card>\n              <CardHeader>\n                <div className=\"flex items-center justify-between\">\n                  <CardTitle>Script Editor</CardTitle>\n                  <div className=\"flex items-center gap-2\">\n                    {hasUnsavedChanges && (\n                      <Badge variant=\"outline\" className=\"text-orange-600\">\n                        <AlertCircle className=\"w-3 h-3 mr-1\" />\n                        Unsaved Changes\n                      </Badge>\n                    )}\n                    <Button\n                      variant=\"outline\"\n                      size=\"sm\"\n                      onClick={() => setIsEditMode(!isEditMode)}\n                    >\n                      {isEditMode ? <Eye className=\"w-4 h-4 mr-2\" /> : <Edit3 className=\"w-4 h-4 mr-2\" />}\n                      {isEditMode ? 'Preview' : 'Edit'}\n                    </Button>\n                  </div>\n                </div>\n              </CardHeader>\n              <CardContent>\n                {isEditMode ? (\n                  <div className=\"space-y-4\">\n                    <Textarea\n                      value={editedScript}\n                      onChange={(e) => handleScriptChange(e.target.value)}\n                      className=\"min-h-[500px] font-mono text-sm\"\n                      placeholder=\"Enter your script content here...\"\n                    />\n                    <div className=\"flex items-center gap-2\">\n                      <Button onClick={handleSaveScript} disabled={!hasUnsavedChanges}>\n                        <Save className=\"w-4 h-4 mr-2\" />\n                        Save Changes\n                      </Button>\n                      <Button variant=\"outline\" onClick={handleResetScript} disabled={!hasUnsavedChanges}>\n                        <RotateCcw className=\"w-4 h-4 mr-2\" />\n                        Reset\n                      </Button>\n                    </div>\n                  </div>\n                ) : (\n                  <div className=\"bg-gray-50 p-4 rounded-lg\">\n                    <pre className=\"whitespace-pre-wrap font-mono text-sm\">\n                      {editedScript || 'No script content available'}\n                    </pre>\n                  </div>\n                )}\n              </CardContent>\n            </Card>\n          </div>\n        )}\n\n        {activeTab === 'pdf' && (\n          <div className=\"space-y-6\">\n            {!pdfAnalysisResults && (\n              <Card>\n                <CardHeader>\n                  <CardTitle>PDF Script Analysis</CardTitle>\n                </CardHeader>\n                <CardContent>\n                  <div className=\"text-center py-8\">\n                    <Upload className=\"w-12 h-12 text-muted-foreground mx-auto mb-4\" />\n                    <h3 className=\"text-lg font-medium mb-2\">Upload Script PDF</h3>\n                    <p className=\"text-muted-foreground mb-4\">\n                      Upload a PDF script file for comprehensive AI analysis\n                    </p>\n                    <input\n                      type=\"file\"\n                      accept=\".pdf\"\n                      onChange={(e) => handlePdfUpload(e as any)}\n                      className=\"hidden\"\n                      id=\"pdf-upload\"\n                    />\n                    <Button\n                      onClick={() => document.getElementById('pdf-upload')?.click()}\n                      disabled={isPdfAnalyzing}\n                    >\n                      {isPdfAnalyzing ? (\n                        <>\n                          <Loader2 className=\"w-4 h-4 mr-2 animate-spin\" />\n                          Analyzing...\n                        </>\n                      ) : (\n                        <>\n                          <Upload className=\"w-4 h-4 mr-2\" />\n                          Choose PDF File\n                        </>\n                      )}\n                    </Button>\n                  </div>\n                </CardContent>\n              </Card>\n            )}\n\n            {isPdfAnalyzing && (\n              <Card>\n                <CardContent className=\"p-6\">\n                  <div className=\"text-center\">\n                    <Loader2 className=\"w-8 h-8 animate-spin mx-auto mb-4\" />\n                    <h3 className=\"text-lg font-medium mb-2\">Analyzing PDF Script</h3>\n                    <p className=\"text-muted-foreground\">\n                      {uploadedPdfName && `Processing: ${uploadedPdfName}`}\n                    </p>\n                  </div>\n                </CardContent>\n              </Card>\n            )}\n\n            {pdfAnalysisError && (\n              <Card className=\"border-red-200\">\n                <CardContent className=\"p-6\">\n                  <div className=\"text-center text-red-600\">\n                    <AlertCircle className=\"w-8 h-8 mx-auto mb-4\" />\n                    <h3 className=\"text-lg font-medium mb-2\">Analysis Failed</h3>\n                    <p>{pdfAnalysisError}</p>\n                  </div>\n                </CardContent>\n              </Card>\n            )}\n\n            {pdfAnalysisResults && (\n              <div className=\"space-y-6\">\n                <Card>\n                  <CardHeader>\n                    <CardTitle className=\"flex items-center gap-2\">\n                      <CheckCircle className=\"w-5 h-5 text-green-600\" />\n                      Analysis Complete\n                    </CardTitle>\n                  </CardHeader>\n                  <CardContent>\n                    <div className=\"grid grid-cols-2 md:grid-cols-4 gap-4\">\n                      <div className=\"text-center\">\n                        <div className=\"text-2xl font-bold text-blue-600\">\n                          {pdfAnalysisResults.data?.totalScenes || pdfAnalysisResults.data?.scenes?.length || 0}\n                        </div>\n                        <div className=\"text-sm text-muted-foreground\">Scenes</div>\n                      </div>\n                      <div className=\"text-center\">\n                        <div className=\"text-2xl font-bold text-green-600\">\n                          {pdfAnalysisResults.data?.totalCharacters || pdfAnalysisResults.data?.characters?.length || 0}\n                        </div>\n                        <div className=\"text-sm text-muted-foreground\">Characters</div>\n                      </div>\n                      <div className=\"text-center\">\n                        <div className=\"text-2xl font-bold text-orange-600\">\n                          {pdfAnalysisResults.data?.totalDialogues || pdfAnalysisResults.data?.dialogues?.length || 0}\n                        </div>\n                        <div className=\"text-sm text-muted-foreground\">Dialogues</div>\n                      </div>\n                      <div className=\"text-center\">\n                        <div className=\"text-2xl font-bold text-purple-600\">\n                          {pdfAnalysisResults.data?.interactions?.length || 0}\n                        </div>\n                        <div className=\"text-sm text-muted-foreground\">Interactions</div>\n                      </div>\n                    </div>\n                    \n                    {pdfAnalysisResults.source && (\n                      <div className=\"mt-4 text-center\">\n                        <Badge variant={pdfAnalysisResults.source === 'cjs' ? 'default' : 'secondary'}>\n                          Analysis Source: {pdfAnalysisResults.source === 'cjs' ? 'CJS API (Fast)' : 'Browser (Fallback)'}\n                        </Badge>\n                      </div>\n                    )}\n                  </CardContent>\n                </Card>\n\n                {/* Scene Breakdown */}\n                {pdfAnalysisResults.data?.scenes && (\n                  <Card>\n                    <CardHeader>\n                      <CardTitle>Scene Breakdown</CardTitle>\n                    </CardHeader>\n                    <CardContent>\n                      <div className=\"space-y-4\">\n                        {pdfAnalysisResults.data.scenes.slice(0, 5).map((scene: any, index: number) => (\n                          <div key={index} className=\"border-l-4 border-blue-500 pl-4\">\n                            <h4 className=\"font-medium\">{scene.Scene_Names || scene.header || `Scene ${index + 1}`}</h4>\n                            <div className=\"flex flex-wrap gap-2 mt-2\">\n                              {scene.Scene_Characters?.map((char: string, i: number) => (\n                                <CategoryBadge key={i} variant=\"cast\">{char}</CategoryBadge>\n                              )) || scene.characters?.map((char: string, i: number) => (\n                                <CategoryBadge key={i} variant=\"cast\">{char}</CategoryBadge>\n                              ))}\n                            </div>\n                            {(scene.Scene_action || scene.summary) && (\n                              <p className=\"text-sm text-muted-foreground mt-2 line-clamp-3\">\n                                {scene.Scene_action || scene.summary}\n                              </p>\n                            )}\n                            {scene.Scene_Dialogue && scene.Scene_Dialogue.length > 0 && (\n                              <div className=\"mt-2\">\n                                <span className=\"text-xs font-medium text-gray-600\">Dialogues: </span>\n                                <span className=\"text-xs text-gray-500\">\n                                  {scene.Scene_Dialogue.slice(0, 2).join(', ')}\n                                  {scene.Scene_Dialogue.length > 2 && '...'}\n                                </span>\n                              </div>\n                            )}\n                          </div>\n                        ))}\n                        {pdfAnalysisResults.data.scenes.length > 5 && (\n                          <p className=\"text-sm text-muted-foreground text-center mt-4\">\n                            And {pdfAnalysisResults.data.scenes.length - 5} more scenes...\n                          </p>\n                        )}\n                      </div>\n                    </CardContent>\n                  </Card>\n                )}\n\n                {/* Characters List */}\n                {pdfAnalysisResults.data?.characters && (\n                  <Card>\n                    <CardHeader>\n                      <CardTitle>Characters</CardTitle>\n                    </CardHeader>\n                    <CardContent>\n                      <div className=\"flex flex-wrap gap-2\">\n                        {pdfAnalysisResults.data.characters.slice(0, 20).map((character: string, index: number) => (\n                          <CategoryBadge key={index} variant=\"cast\">{character}</CategoryBadge>\n                        ))}\n                        {pdfAnalysisResults.data.characters.length > 20 && (\n                          <span className=\"text-sm text-muted-foreground\">\n                            +{pdfAnalysisResults.data.characters.length - 20} more\n                          </span>\n                        )}\n                      </div>\n                    </CardContent>\n                  </Card>\n                )}\n\n                {/* Character Interactions */}\n                {pdfAnalysisResults.data?.interactions && pdfAnalysisResults.data.interactions.length > 0 && (\n                  <Card>\n                    <CardHeader>\n                      <CardTitle>Character Interactions</CardTitle>\n                    </CardHeader>\n                    <CardContent>\n                      <div className=\"space-y-2\">\n                        {pdfAnalysisResults.data.interactions.slice(0, 10).map((interaction: any, index: number) => (\n                          <div key={index} className=\"flex items-center justify-between\">\n                            <span className=\"text-sm\">{interaction.pair}</span>\n                            <Badge variant=\"outline\">{interaction.count} scenes</Badge>\n                          </div>\n                        ))}\n                        {pdfAnalysisResults.data.interactions.length > 10 && (\n                          <p className=\"text-sm text-muted-foreground text-center mt-4\">\n                            And {pdfAnalysisResults.data.interactions.length - 10} more interactions...\n                          </p>\n                        )}\n                      </div>\n                    </CardContent>\n                  </Card>\n                )}\n              </div>\n            )}\n\n            {/* Background Processing Status */}\n            {(isGeneratingSchedule || isGeneratingBudget || backgroundProcessStatus) && (\n              <Card className=\"border-blue-200\">\n                <CardHeader>\n                  <CardTitle className=\"flex items-center gap-2\">\n                    <Loader2 className=\"w-5 h-5 animate-spin text-blue-600\" />\n                    Background Processing\n                  </CardTitle>\n                </CardHeader>\n                <CardContent>\n                  <p className=\"text-sm text-muted-foreground mb-4\">\n                    {backgroundProcessStatus}\n                  </p>\n                  <div className=\"flex items-center gap-4\">\n                    <div className=\"flex items-center gap-2\">\n                      {isGeneratingSchedule ? (\n                        <Loader2 className=\"w-4 h-4 animate-spin text-blue-600\" />\n                      ) : (\n                        <CheckCircle className=\"w-4 h-4 text-green-600\" />\n                      )}\n                      <span className=\"text-sm\">Schedule Generation</span>\n                    </div>\n                    <div className=\"flex items-center gap-2\">\n                      {isGeneratingBudget ? (\n                        <Loader2 className=\"w-4 h-4 animate-spin text-blue-600\" />\n                      ) : backgroundProcessComplete ? (\n                        <CheckCircle className=\"w-4 h-4 text-green-600\" />\n                      ) : (\n                        <Clock className=\"w-4 h-4 text-gray-400\" />\n                      )}\n                      <span className=\"text-sm\">Budget Generation</span>\n                    </div>\n                  </div>\n                </CardContent>\n              </Card>\n            )}\n          </div>\n        )}\n\n        {activeTab === 'depth' && (\n          <div className=\"space-y-6\">\n            <Card>\n              <CardHeader>\n                <CardTitle>Depth Analysis</CardTitle>\n                <p className=\"text-sm text-muted-foreground\">\n                  Advanced 4-agent pipeline analysis for comprehensive script breakdown\n                </p>\n              </CardHeader>\n              <CardContent>\n                <div className=\"space-y-4\">\n                  <Button\n                    onClick={handleDepthAnalysis}\n                    disabled={isDepthAnalyzing || !selectedProject?.scriptContent}\n                    className=\"w-full\"\n                  >\n                    {isDepthAnalyzing ? (\n                      <>\n                        <Loader2 className=\"w-4 h-4 mr-2 animate-spin\" />\n                        Running Depth Analysis... ({depthAnalysisProgress}%)\n                      </>\n                    ) : (\n                      <>\n                        <Brain className=\"w-4 h-4 mr-2\" />\n                        Start Depth Analysis\n                      </>\n                    )}\n                  </Button>\n\n                  {isDepthAnalyzing && (\n                    <div className=\"space-y-2\">\n                      <div className=\"flex justify-between text-sm\">\n                        <span>Progress: {currentDepthAgent}</span>\n                        <span>{depthAnalysisProgress}%</span>\n                      </div>\n                      <div className=\"w-full bg-gray-200 rounded-full h-2\">\n                        <div\n                          className=\"bg-blue-600 h-2 rounded-full transition-all duration-300\"\n                          style={{ width: `${depthAnalysisProgress}%` }}\n                        ></div>\n                      </div>\n                    </div>\n                  )}\n\n                  {depthAnalysisError && (\n                    <div className=\"text-red-600 text-sm\">\n                      <AlertCircle className=\"w-4 h-4 mr-2 inline\" />\n                      {depthAnalysisError}\n                    </div>\n                  )}\n                </div>\n              </CardContent>\n            </Card>\n\n            {depthAnalysisResults && showDepthResults && (\n              <Card>\n                <CardHeader>\n                  <CardTitle className=\"flex items-center gap-2\">\n                    <CheckCircle className=\"w-5 h-5 text-green-600\" />\n                    Depth Analysis Results\n                  </CardTitle>\n                </CardHeader>\n                <CardContent>\n                  <div className=\"space-y-4\">\n                    <div className=\"grid grid-cols-2 md:grid-cols-4 gap-4\">\n                      <div className=\"text-center\">\n                        <div className=\"text-2xl font-bold text-blue-600\">\n                          {depthAnalysisResults.totalScenes || 0}\n                        </div>\n                        <div className=\"text-sm text-muted-foreground\">Scenes Analyzed</div>\n                      </div>\n                      <div className=\"text-center\">\n                        <div className=\"text-2xl font-bold text-green-600\">\n                          {depthAnalysisResults.totalCharacters || 0}\n                        </div>\n                        <div className=\"text-sm text-muted-foreground\">Characters</div>\n                      </div>\n                      <div className=\"text-center\">\n                        <div className=\"text-2xl font-bold text-orange-600\">\n                          {depthAnalysisResults.totalLocations || 0}\n                        </div>\n                        <div className=\"text-sm text-muted-foreground\">Locations</div>\n                      </div>\n                      <div className=\"text-center\">\n                        <div className=\"text-2xl font-bold text-purple-600\">\n                          4\n                        </div>\n                        <div className=\"text-sm text-muted-foreground\">AI Agents</div>\n                      </div>\n                    </div>\n\n                    {depthAnalysisResults.summary && (\n                      <div className=\"bg-gray-50 p-4 rounded-lg\">\n                        <h4 className=\"font-medium mb-2\">Analysis Summary</h4>\n                        <p className=\"text-sm text-muted-foreground\">\n                          {depthAnalysisResults.summary}\n                        </p>\n                      </div>\n                    )}\n                  </div>\n                </CardContent>\n              </Card>\n            )}\n          </div>\n        )}\n      </div>\n    </div>\n  );\n}",
/Users/varunisrani/Downloads/filmustage-ui-kit-main/think.ai/logs/post_tool_use.json:11722:        "content": "import { GoogleGenAI } from \"@google/genai\";\n\n// Input Types (from Script Analysis)\nexport interface ScriptAnalysisInput {\n  sceneBreakdownOutput: {\n    projectId: string;\n    sceneAnalysisSummary: {\n      totalScenesProcessed: number;\n      totalCharactersIdentified: number;\n      totalLocationsIdentified: number;\n      totalPropsIdentified: number;\n      averageSceneComplexity: number;\n    };\n    detailedSceneBreakdowns: Array<{\n      sceneNumber: number;\n      sceneHeader: string;\n      location: {\n        type: \"INT\" | \"EXT\";\n        primaryLocation: string;\n        timeOfDay: string;\n        complexityLevel: \"simple\" | \"moderate\" | \"complex\" | \"extreme\";\n      };\n      characters: {\n        speaking: Array<{\n          name: string;\n          dialogueLines: number;\n          specialRequirements: string[];\n        }>;\n        nonSpeaking: Array<{\n          description: string;\n          count: number;\n        }>;\n      };\n      timeEstimates: {\n        setupHours: number;\n        shootingHours: number;\n        wrapHours: number;\n        totalHours: number;\n      };\n      complexityScores: {\n        technicalDifficulty: number;\n        castComplexity: number;\n        locationChallenges: number;\n        overallComplexity: number;\n      };\n      departmentRequirements: {\n        makeup: {\n          standardMakeup: number;\n          estimatedApplicationTime: number;\n        };\n        wardrobe: {\n          standardCostumes: number;\n        };\n      };\n      specialConsiderations: string[];\n    }>;\n  };\n}\n\n// Output Types (Generated Scheduling Data)\nexport interface ProductionScheduleOutput {\n  scheduleOverview: {\n    projectId: string;\n    totalShootDays: number;\n    estimatedBudgetRange: {\n      low: number;\n      high: number;\n    };\n    recommendedCrewSize: number;\n    productionTimeline: {\n      prepDays: number;\n      shootDays: number;\n      wrapDays: number;\n    };\n  };\n  dailySchedule: Array<{\n    day: number;\n    date: string;\n    location: string;\n    scenes: Array<{\n      sceneNumber: number;\n      startTime: string;\n      endTime: string;\n      duration: number;\n    }>;\n    castNeeded: string[];\n    crewSize: number;\n    estimatedCost: number;\n  }>;\n  castSchedule: Array<{\n    characterName: string;\n    workDays: number[];\n    totalDays: number;\n    estimatedCost: number;\n  }>;\n  locationSchedule: Array<{\n    location: string;\n    scenes: number[];\n    days: number[];\n    setupRequirements: string[];\n    estimatedCost: number;\n  }>;\n  complexScenes: Array<{\n    sceneNumber: number;\n    reason: string;\n    recommendation: string;\n    priority: \"high\" | \"medium\" | \"low\";\n  }>;\n  departmentNeeds: {\n    makeup: {\n      dailyRequirements: Array<{\n        day: number;\n        artistsNeeded: number;\n        setupTime: number;\n      }>;\n    };\n    wardrobe: {\n      dailyRequirements: Array<{\n        day: number;\n        costumesNeeded: number;\n      }>;\n    };\n  };\n  budgetBreakdown: {\n    cast: number;\n    crew: number;\n    equipment: number;\n    locations: number;\n    postProduction: number;\n    contingency: number;\n    total: number;\n  };\n  riskAssessment: Array<{\n    type: \"weather\" | \"cast\" | \"location\" | \"equipment\" | \"budget\";\n    description: string;\n    impact: \"high\" | \"medium\" | \"low\";\n    mitigation: string;\n  }>;\n  // Phase 2 Enhanced Features\n  equipmentSchedule: Array<{\n    equipmentType: string;\n    scenes: number[];\n    days: number[];\n    rentalCost: number;\n    setupTime: number;\n    conflicts: string[];\n  }>;\n  departmentWorkload: {\n    makeup: Array<{\n      day: number;\n      artistsNeeded: number;\n      complexity: \"standard\" | \"complex\" | \"extreme\";\n      setupHours: number;\n      specialRequirements: string[];\n    }>;\n    wardrobe: Array<{\n      day: number;\n      costumesNeeded: number;\n      quickChanges: number;\n      fittingTime: number;\n      specialRequirements: string[];\n    }>;\n    props: Array<{\n      day: number;\n      propsNeeded: string[];\n      setupTime: number;\n      specialHandling: string[];\n    }>;\n  };\n  conflictAnalysis: {\n    castConflicts: Array<{\n      characterName: string;\n      conflictDays: number[];\n      severity: \"high\" | \"medium\" | \"low\";\n      resolution: string;\n    }>;\n    equipmentConflicts: Array<{\n      equipmentType: string;\n      conflictDays: number[];\n      affectedScenes: number[];\n      resolution: string;\n    }>;\n    locationConflicts: Array<{\n      location: string;\n      conflictDays: number[];\n      issue: string;\n      resolution: string;\n    }>;\n  };\n  optimizationMetrics: {\n    locationEfficiency: number; // 0-100%\n    castUtilization: number; // 0-100%\n    equipmentUtilization: number; // 0-100%\n    overallEfficiency: number; // 0-100%\n    estimatedSavings: number; // Dollar amount saved vs basic schedule\n  };\n}\n\n// System Prompt for Scheduling Generation\nconst SCHEDULING_GENERATOR_SYSTEM_PROMPT = `\nFILM PRODUCTION SCHEDULING GENERATOR\n====================================\n\nYou are an AI Production Scheduler that converts detailed script analysis data into practical filming schedules. Your role is to create realistic, budget-conscious shooting schedules that optimize efficiency while maintaining quality.\n\n## Core Responsibilities\n\n1. **Schedule Optimization**\n   - Group scenes by location to minimize moves and setup time\n   - Sequence scenes to maximize cast and crew efficiency\n   - Balance daily workload to maintain quality while meeting deadlines\n   - Account for setup, shooting, and wrap time for each scene\n\n2. **Budget Estimation**\n   - Calculate realistic cost estimates based on scene complexity and requirements\n   - Factor in cast days, crew size, equipment rental, and location costs\n   - Provide low/high budget ranges with contingency planning\n   - Break down costs by department and production phase\n\n3. **Resource Planning**\n   - Generate cast Day-Out-of-Days (DOOD) schedules\n   - Calculate optimal crew size based on scene requirements\n   - Plan equipment and department resource allocation\n   - Identify potential conflicts and bottlenecks\n\n4. **Risk Management**\n   - Flag high-complexity scenes requiring special attention\n   - Identify weather-dependent scenes needing backup plans\n   - Highlight potential scheduling conflicts\n   - Provide mitigation strategies for identified risks\n\n## Scheduling Principles\n\n### Location Grouping Strategy (Phase 2 Enhanced)\n- **Smart Location Clustering**: Group scenes by location proximity and type\n- **Company Move Optimization**: Calculate travel time and minimize expensive moves\n- **Weather Contingency Planning**: Schedule interior scenes as backup for weather-dependent exteriors\n- **Location Access Windows**: Account for permit restrictions and availability\n- **Setup Cost Amortization**: Maximize location usage to spread setup costs\n\n### Cast Efficiency Optimization (Phase 2 Enhanced)\n- **Day-Out-of-Days Optimization**: Minimize actor holding days and maximize continuity\n- **Character Arc Scheduling**: Group scenes by character development flow when possible\n- **Union Compliance**: Automatic turnaround time and rest period calculations\n- **Makeup/Wardrobe Efficiency**: Schedule cast changes to minimize department workload\n- **Conflict Detection**: Identify and resolve cast availability conflicts\n\n### Equipment & Department Scheduling (Phase 2)\n- **Equipment Rental Optimization**: Group scenes requiring specialized equipment\n- **Department Resource Planning**: Calculate daily needs for makeup, wardrobe, props\n- **Equipment Conflict Detection**: Identify double-bookings and resource bottlenecks  \n- **Crew Size Optimization**: Adjust crew size based on daily requirements\n- **Department Setup Time**: Account for prep time needed by each department\n\n### Daily Schedule Structure (Enhanced)\n- **Flexible Day Length**: Optimize between 8-12 hour days based on content\n- **Complexity-Based Scheduling**: Schedule demanding scenes when crew is fresh\n- **Meal Break Optimization**: Strategic meal timing to maximize momentum\n- **Setup/Strike Efficiency**: Minimize daily setup and breakdown time\n- **Contingency Time Allocation**: Build in buffer time for complex scenes\n\n### Budget Calculation Guidelines (Phase 2 Enhanced)\n- **Cast**: $500-2000/day per principal, $150-300/day per supporting, includes holding days\n- **Crew**: $300-800/day per crew member, variable by department and specialization\n- **Equipment**: $500-2000/day for basic packages, $1000-5000/day for specialized gear\n- **Locations**: $500-5000/day plus travel and setup costs, permit fees\n- **Department Costs**: Makeup ($200-800/day), Wardrobe ($300-1000/day), Props ($100-500/day)\n- **Post-production**: 15-25% of production budget, varies by complexity\n- **Contingency**: 10-15% buffer for unforeseen costs and schedule changes\n\n## MANDATORY OUTPUT FORMAT\n\n**CRITICAL: Return ONLY a complete, valid JSON object following this exact structure:**\n\n\\`\\`\\`json\n{\n  \"scheduleOverview\": {\n    \"projectId\": \"string\",\n    \"totalShootDays\": \"number\",\n    \"estimatedBudgetRange\": {\n      \"low\": \"number\",\n      \"high\": \"number\"\n    },\n    \"recommendedCrewSize\": \"number\",\n    \"productionTimeline\": {\n      \"prepDays\": \"number\",\n      \"shootDays\": \"number\", \n      \"wrapDays\": \"number\"\n    }\n  },\n  \"dailySchedule\": [\n    {\n      \"day\": \"number\",\n      \"date\": \"YYYY-MM-DD\",\n      \"location\": \"string\",\n      \"scenes\": [\n        {\n          \"sceneNumber\": \"number\",\n          \"startTime\": \"HH:MM\",\n          \"endTime\": \"HH:MM\", \n          \"duration\": \"number_hours\"\n        }\n      ],\n      \"castNeeded\": [\"array_of_character_names\"],\n      \"crewSize\": \"number\",\n      \"estimatedCost\": \"number\"\n    }\n  ],\n  \"castSchedule\": [\n    {\n      \"characterName\": \"string\",\n      \"workDays\": [\"array_of_day_numbers\"],\n      \"totalDays\": \"number\",\n      \"estimatedCost\": \"number\"\n    }\n  ],\n  \"locationSchedule\": [\n    {\n      \"location\": \"string\",\n      \"scenes\": [\"array_of_scene_numbers\"],\n      \"days\": [\"array_of_day_numbers\"],\n      \"setupRequirements\": [\"array_of_requirements\"],\n      \"estimatedCost\": \"number\"\n    }\n  ],\n  \"complexScenes\": [\n    {\n      \"sceneNumber\": \"number\",\n      \"reason\": \"string\",\n      \"recommendation\": \"string\",\n      \"priority\": \"high|medium|low\"\n    }\n  ],\n  \"departmentNeeds\": {\n    \"makeup\": {\n      \"dailyRequirements\": [\n        {\n          \"day\": \"number\",\n          \"artistsNeeded\": \"number\",\n          \"setupTime\": \"number_minutes\"\n        }\n      ]\n    },\n    \"wardrobe\": {\n      \"dailyRequirements\": [\n        {\n          \"day\": \"number\",\n          \"costumesNeeded\": \"number\"\n        }\n      ]\n    }\n  },\n  \"budgetBreakdown\": {\n    \"cast\": \"number\",\n    \"crew\": \"number\", \n    \"equipment\": \"number\",\n    \"locations\": \"number\",\n    \"postProduction\": \"number\",\n    \"contingency\": \"number\",\n    \"total\": \"number\"\n  },\n  \"riskAssessment\": [\n    {\n      \"type\": \"weather|cast|location|equipment|budget\",\n      \"description\": \"string\",\n      \"impact\": \"high|medium|low\", \n      \"mitigation\": \"string\"\n    }\n  ],\n  \"equipmentSchedule\": [\n    {\n      \"equipmentType\": \"string\",\n      \"scenes\": [\"array_of_scene_numbers\"],\n      \"days\": [\"array_of_day_numbers\"],\n      \"rentalCost\": \"number\",\n      \"setupTime\": \"number_minutes\",\n      \"conflicts\": [\"array_of_conflict_desc