                                          ? dialogue.substring(0, 100) + '...' 
                                          : dialogue }"
                                    </div>
                                  ))}
                                  {!showAllScenes && scene.Scene_Dialogue.length > 3 && (
                                    <div className="text-xs text-blue-600 mt-2">
