                                    </div>
                                  )}
                                </div>
                              </div>
                            )}
                          </div>
                        ))}

                        {!showAllScenes && pdfAnalysisResults.data.scenes.length > 5 && (
                          <div className="text-center py-4">
                            <Button
                              variant="outline"
                              onClick={() => setShowAllScenes(true)}
                            >
