                </div>

                {/* Production Timeline */}
                {productionSchedule.scheduleOverview?.productionTimeline && (
                  <Card>
                    <CardHeader>
                      <CardTitle>Production Timeline</CardTitle>
                    </CardHeader>
                    <CardContent>
                      <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
