                          </div>
                        ))}
                      </div>
                    </div>
                  )}
                </CardContent>
              </Card>
            )}
          </div>
        )}

        {/* Individual Budget Service Tabs */}
        {['coordinator', 'labor', 'equipment', 'location', 'schedule', 'insurance', 'postprod', 'tax', 'aggregator', 'cashflow'].includes(activeTab) && (
          <div className="space-y-6">
            <Card>
              <CardHeader>
                <CardTitle className="capitalize">{activeTab.replace(/([A-Z])/g, ' $1')} Service</CardTitle>
                <p className="text-sm text-muted-foreground">
                  Individual AI service for specialized budget analysis
                </p>
              </CardHeader>
              <CardContent>
                <div className="space-y-4">
                  <div>
                    <label className="block text-sm font-medium mb-2">
                      JSON Input (optional - will use project data if empty)
                    </label>
                    <Textarea
                      placeholder="Enter JSON input for this service or leave empty to use project data"
                      value={(() => {
                        const inputs = {
                          coordinator: jsonInputBudgetCoordinator,
                          labor: jsonInputLaborCost,
                          equipment: jsonInputEquipmentPricing,
                          location: jsonInputLocationCost,
                          schedule: jsonInputScheduleOptimizer,
                          insurance: jsonInputInsuranceCalculator,
                          postprod: jsonInputPostProductionEstimator,
                          tax: jsonInputTaxIncentiveAnalyzer,
                          aggregator: jsonInputBudgetAggregator,
                          cashflow: jsonInputCashFlowProjector
                        };
                        return inputs[activeTab as keyof typeof inputs] || '';
                      })()}
                      onChange={(e) => {
                        const setters = {
                          coordinator: setJsonInputBudgetCoordinator,
                          labor: setJsonInputLaborCost,
                          equipment: setJsonInputEquipmentPricing,
                          location: setJsonInputLocationCost,
                          schedule: setJsonInputScheduleOptimizer,
                          insurance: setJsonInputInsuranceCalculator,
                          postprod: setJsonInputPostProductionEstimator,
                          tax: setJsonInputTaxIncentiveAnalyzer,
                          aggregator: setJsonInputBudgetAggregator,
                          cashflow: setJsonInputCashFlowProjector
                        };
                        const setter = setters[activeTab as keyof typeof setters];
                        if (setter) setter(e.target.value);
                      }}
                      className="min-h-[120px] font-mono text-sm"
                    />
                  </div>

                  <Button 
                    onClick={() => handleBudgetServiceAnalysis(activeTab)}
                    disabled={(() => {
                      const analyzing = {
                        coordinator: isAnalyzingBudgetCoordinator,
                        labor: isAnalyzingLaborCost,
                        equipment: isAnalyzingEquipmentPricing,
                        location: isAnalyzingLocationCost,
                        schedule: isAnalyzingScheduleOptimizer,
                        insurance: isAnalyzingInsuranceCalculator,
                        postprod: isAnalyzingPostProductionEstimator,
                        tax: isAnalyzingTaxIncentiveAnalyzer,
                        aggregator: isAnalyzingBudgetAggregator,
                        cashflow: isAnalyzingCashFlowProjector
                      };
                      return analyzing[activeTab as keyof typeof analyzing] || false;
                    })()}
                    className="w-full"
                  >
                    {(() => {
                      const analyzing = {
                        coordinator: isAnalyzingBudgetCoordinator,
                        labor: isAnalyzingLaborCost,
                        equipment: isAnalyzingEquipmentPricing,
                        location: isAnalyzingLocationCost,
                        schedule: isAnalyzingScheduleOptimizer,
                        insurance: isAnalyzingInsuranceCalculator,
                        postprod: isAnalyzingPostProductionEstimator,
                        tax: isAnalyzingTaxIncentiveAnalyzer,
                        aggregator: isAnalyzingBudgetAggregator,
                        cashflow: isAnalyzingCashFlowProjector
                      };
                      return analyzing[activeTab as keyof typeof analyzing];
                    })() ? (
                      <>
                        <Loader2 className="w-4 h-4 mr-2 animate-spin" />
                        Analyzing...
                      </>
                    ) : (
                      <>
                        <Brain className="w-4 h-4 mr-2" />
                        Analyze with AI
                      </>
                    )}
                  </Button>

                  {(() => {
                    const errors = {
                      coordinator: budgetCoordinatorError,
                      labor: laborCostError,
                      equipment: equipmentPricingError,
                      location: locationCostError,
                      schedule: scheduleOptimizerError,
                      insurance: insuranceCalculatorError,
                      postprod: postProductionEstimatorError,
                      tax: taxIncentiveAnalyzerError,
                      aggregator: budgetAggregatorError,
                      cashflow: cashFlowProjectorError
                    };
                    const error = errors[activeTab as keyof typeof errors];
                    return error && (
                      <div className="text-red-600 text-sm">
                        <AlertTriangle className="w-4 h-4 mr-2 inline" />
                        {error}
                      </div>
                    );
                  })()}
                </div>
              </CardContent>
            </Card>

            {/* Service Results */}
            {(() => {
              const results = {
                coordinator: budgetCoordinatorResult,
                labor: laborCostResult,
                equipment: equipmentPricingResult,
                location: locationCostResult,
                schedule: scheduleOptimizerResult,
                insurance: insuranceCalculatorResult,
                postprod: postProductionEstimatorResult,
                tax: taxIncentiveAnalyzerResult,
                aggregator: budgetAggregatorResult,
                cashflow: cashFlowProjectorResult
              };
              const result = results[activeTab as keyof typeof results];

              return result && (
                <Card>
                  <CardHeader>
                    <CardTitle className="flex items-center gap-2">
                      <CheckCircle className="w-5 h-5 text-green-600" />
                      {activeTab.charAt(0).toUpperCase() + activeTab.slice(1)} Results
                    </CardTitle>
                  </CardHeader>
                  <CardContent>
                    <div className="bg-gray-50 p-4 rounded-lg">
                      <div className="flex items-center justify-between mb-2">
                        <h4 className="font-medium">Analysis Results</h4>
                        <Button
                          variant="outline"
                          size="sm"
                          onClick={() => toggleRawSection(activeTab)}
                        >
                          {expandedRawSections[activeTab] ? (
                            <>
                              <ChevronUp className="w-4 h-4 mr-2" />
                              Hide Details
                            </>
                          ) : (
                            <>
                              <ChevronDown className="w-4 h-4 mr-2" />
                              Show Details
                            </>
                          )}
                        </Button>
                      </div>

                      {expandedRawSections[activeTab] && (
                        <pre className="text-sm bg-white p-3 rounded border overflow-auto max-h-96">
                          {JSON.stringify(result, null, 2)}
                        </pre>
                      )}

                      {!expandedRawSections[activeTab] && (
                        <div className="text-sm text-muted-foreground">
                          Analysis completed successfully. Click "Show Details" to view full results.
                        </div>
                      )}
                    </div>
                  </CardContent>
                </Card>
              );
            })()}
          </div>
        )}
        </div>
      </div>
    </div>
  );
}

tool_input.content:
/**
 * AI Depth Budget Analysis Service
 * ================================
 * 
 * JavaScript implementation of the 2001 Budget Pipeline
 * 4-Agent Tier-Based Production Budget System
 * 
 * Architecture:
 * - Tier 1: Budget Coordinator Agent (data distribution orchestrator)
 * - Tier 2: Cost Calculator + Resource Estimator (parallel execution)
 * - Tier 3: Optimization Scenario Agent (synthesizes all outputs)
 */

import { GoogleGenerativeAI } from '@google/generative-ai';

// Type definitions for budget analysis
interface BudgetProject {
  id: string;
  name: string;
  scriptContent: string;
  analysisData?: any;
  scheduleData?: any;
  created: string;
}

interface TierProgress {
  tierNumber: number;
  tierName: string;
  agents: string[];
  progress: number;
  status: 'pending' | 'running' | 'completed' | 'failed';
}

interface AgentResult {
  result: any;
  rawResponse: string;
  processingTime: number;
  success: boolean;
  errors?: string[];
}

interface BudgetScenario {
  scenarioName: string;
  scenarioType: 'baseline' | 'cost-optimized' | 'quality-optimized' | 'risk-mitigated';
  budgetSummary: {
    totalBudget: number;
    shootDays: number;
    riskScore: number;
    qualityScore: number;
  };
  budgetBreakdown: BudgetCategory[];
  departmentBudgets: DepartmentBudget[];
  costAnalysis: CostAnalysis;
  riskAssessment: RiskAssessment;
}

interface BudgetCategory {
  categoryId: string;
  categoryName: string;
  totalAmount: number;
  percentage: number;
  lineItems: LineItem[];
  contingency: number;
}

interface LineItem {
  itemId: string;
  description: string;
  quantity: number;
  unitCost: number;
  totalCost: number;
  department: string;
  priority: 'essential' | 'important' | 'optional';
}

interface DepartmentBudget {
  department: string;
  totalBudget: number;
  dailyBudget: number;
  resourceAllocation: ResourceAllocation[];
  costEfficiency: number;
}

interface ResourceAllocation {
  resourceType: string;
  quantity: number;
  costPerUnit: number;
  totalCost: number;
  utilizationRate: number;
}

interface CostAnalysis {
  directCosts: number;
  indirectCosts: number;
  contingencyFunds: number;
  totalProjectCost: number;
  costPerDay: number;
  costPerScene: number;
}

interface RiskAssessment {
  budgetOverrunRisk: number;
  scheduleImpactRisk: number;
  qualityCompromiseRisk: number;
  overallRiskScore: number;
  mitigationStrategies: string[];
}

interface DepthBudgetResult {
  projectId: string;
  executionMetadata: {
    startTime: string;
    endTime: string;
    totalProcessingTime: number;
    tierResults: TierProgress[];
  };
  scenarios: BudgetScenario[];
  rawAgentOutputs: {
    coordinatorRaw: string;
    costCalculatorRaw: string;
    resourceEstimatorRaw: string;
    optimizationRaw: string;
  };
  recommendedScenario: string;
  summary: {
    optimalBudget: number;
    budgetRange: string;
    majorCostDrivers: string[];
    budgetRecommendations: string[];
  };
  complianceReport?: {
    unionBudgetCompliance: any;
    insuranceRequirements: any;
    taxIncentiveOpportunities: any;
  };
}

export class DepthBudgetAnalysisService {
  private genAI: GoogleGenerativeAI;
  private model: any;

  constructor() {
    const apiKey = process.env.NEXT_PUBLIC_GEMINI_API_KEY || "AIzaSyABISxaNzifdIcZUCe408LoKnEz0bia8cI";
    if (!apiKey) {
      throw new Error('NEXT_PUBLIC_GEMINI_API_KEY environment variable is required');
    }

    this.genAI = new GoogleGenerativeAI(apiKey);
    this.model = this.genAI.getGenerativeModel({ 
      model: "gemini-2.5-pro",
      generationConfig: {
        temperature: 0.3,
        topP: 0.8,
        maxOutputTokens: 8192,
      }
    });
  }

  /**
   * Execute the complete 4-agent tier-based budget analysis pipeline
   */
  async executeFullBudgetAnalysis(
    project: BudgetProject,
    onProgress?: (message: string, agent: string, progress: number, tier?: number) => void,
    onTierComplete?: (tier: TierProgress) => void
  ): Promise<DepthBudgetResult> {
    const startTime = new Date().toISOString();
    console.log('💰 Starting AI Depth Budget Analysis Pipeline');

    // Initialize tier progress tracking
    const tierResults: TierProgress[] = [
      { tierNumber: 1, tierName: 'Budget Coordinator', agents: ['Coordinator'], progress: 0, status: 'pending' },
      { tierNumber: 2, tierName: 'Parallel Analysis', agents: ['Cost Calculator', 'Resource Estimator'], progress: 0, status: 'pending' },
      { tierNumber: 3, tierName: 'Optimization', agents: ['Scenario Optimization'], progress: 0, status: 'pending' }
    ];

    let rawAgentOutputs = {
      coordinatorRaw: '',
      costCalculatorRaw: '',
      resourceEstimatorRaw: '',
      optimizationRaw: ''
    };

    try {
      // TIER 1: Budget Coordinator Agent - Data Distribution Orchestrator
      onProgress?.('💰 Tier 1: Budget Coordinator analyzing project and distributing data...', 'Coordinator', 15, 1);
      tierResults[0].status = 'running';

      const { result: coordinatorResult, rawResponse: coordinatorRaw } = await this.executeBudgetCoordinatorAgent(
        project,
        project.id,
        startTime
      );

      rawAgentOutputs.coordinatorRaw = coordinatorRaw;
      tierResults[0].progress = 100;
      tierResults[0].status = 'completed';
      onTierComplete?.(tierResults[0]);

      console.log('✅ Tier 1 Complete: Budget Coordinator Agent finished');

      // TIER 2: Parallel Execution - Cost Calculator + Resource Estimator
      onProgress?.('💸 Tier 2: Parallel analysis - Cost calculation & Resource estimation...', 'Parallel Analysis', 40, 2);
      tierResults[1].status = 'running';

      // Execute both agents in parallel
      const [costCalculatorResult, resourceEstimatorResult] = await Promise.all([
        this.executeCostCalculatorAgent(coordinatorResult, project.id, startTime),
        this.executeResourceEstimatorAgent(coordinatorResult, project.id, startTime)
      ]);

      rawAgentOutputs.costCalculatorRaw = costCalculatorResult.rawResponse;
      rawAgentOutputs.resourceEstimatorRaw = resourceEstimatorResult.rawResponse;

      tierResults[1].progress = 100;
      tierResults[1].status = 'completed';
      onTierComplete?.(tierResults[1]);

      console.log('✅ Tier 2 Complete: Cost Calculator & Resource Estimator agents finished');

      // TIER 3: Optimization Scenario Agent - Budget Optimization
      onProgress?.('🎯 Tier 3: Budget optimization generating 4 scenarios...', 'Scenario Optimization', 75, 3);
      tierResults[2].status = 'running';

      const { result: optimizationResult, rawResponse: optimizationRaw } = await this.executeBudgetOptimizationAgent(
        coordinatorResult,
        costCalculatorResult.result,
        resourceEstimatorResult.result,
        project.id,
        startTime
      );

      rawAgentOutputs.optimizationRaw = optimizationRaw;
      tierResults[2].progress = 100;
      tierResults[2].status = 'completed';
      onTierComplete?.(tierResults[2]);

      console.log('✅ Tier 3 Complete: Budget Optimization Agent finished');

      // Final compilation and recommendation
      onProgress?.('📊 Compiling final budget analysis...', 'Final Analysis', 95, 3);

      const endTime = new Date().toISOString();
      const totalProcessingTime = new Date(endTime).getTime() - new Date(startTime).getTime();

      // Compile final results
      const finalResult: DepthBudgetResult = {
        projectId: project.id,
        executionMetadata: {
          startTime,
          endTime,
          totalProcessingTime,
          tierResults
        },
        scenarios: optimizationResult.scenarios || [],
        rawAgentOutputs,
        recommendedScenario: optimizationResult.recommendedScenario || 'cost-optimized',
        summary: {
          optimalBudget: optimizationResult.summary?.optimalBudget || 2500000,
          budgetRange: optimizationResult.summary?.budgetRange || '$2.2M - $2.8M',
          majorCostDrivers: optimizationResult.summary?.majorCostDrivers || ['Cast salaries', 'Equipment rentals', 'Location fees'],
          budgetRecommendations: optimizationResult.summary?.budgetRecommendations || ['Consider equipment purchase vs rental', 'Optimize location schedules', 'Negotiate cast deals']
        },
        complianceReport: optimizationResult.complianceReport
      };

      onProgress?.('✅ AI Depth Budget Analysis Complete!', 'Complete', 100, 3);
      console.log('🎉 Complete AI Depth Budget Analysis Pipeline Finished');

      return finalResult;

    } catch (error) {
      console.error('❌ Budget Analysis Pipeline Error:', error);

      // Mark current tier as failed
      const currentTier = tierResults.find(t => t.status === 'running');
      if (currentTier) {
        currentTier.status = 'failed';
      }

      // Return error result with available data
      return {
        projectId: project.id,
        executionMetadata: {
          startTime,
          endTime: new Date().toISOString(),
          totalProcessingTime: new Date().getTime() - new Date(startTime).getTime(),
          tierResults
        },
        scenarios: [],
        rawAgentOutputs,
        recommendedScenario: 'baseline',
        summary: {
          optimalBudget: 0,
          budgetRange: 'Analysis Failed',
          majorCostDrivers: ['Pipeline execution error'],
          budgetRecommendations: ['Restart analysis']
        }
      };
    }
  }

