  /**
   * Execute the complete 4-agent tier-based budget analysis pipeline
   */
  async executeFullBudgetAnalysis(
    project: BudgetProject,
    onProgress?: (message: string, agent: string, progress: number, tier?: number) => void,
    onTierComplete?: (tier: TierProgress) => void
  ): Promise<DepthBudgetResult> {
    const startTime = new Date().toISOString();
    console.log('💰 Starting AI Depth Budget Analysis Pipeline');

    // Initialize tier progress tracking
    const tierResults: TierProgress[] = [
      { tierNumber: 1, tierName: 'Budget Coordinator', agents: ['Coordinator'], progress: 0, status: 'pending' },
      { tierNumber: 2, tierName: 'Parallel Analysis', agents: ['Cost Calculator', 'Resource Estimator'], progress: 0, status: 'pending' },
      { tierNumber: 3, tierName: 'Optimization', agents: ['Scenario Optimization'], progress: 0, status: 'pending' }
    ];

    let rawAgentOutputs = {
      coordinatorRaw: '',
      costCalculatorRaw: '',
      resourceEstimatorRaw: '',
      optimizationRaw: ''
    };

    try {
      // TIER 1: Budget Coordinator Agent - Data Distribution Orchestrator
      onProgress?.('💰 Tier 1: Budget Coordinator analyzing project and distributing data...', 'Coordinator', 15, 1);
      tierResults[0].status = 'running';

      const { result: coordinatorResult, rawResponse: coordinatorRaw } = await this.executeBudgetCoordinatorAgent(
        project,
        project.id,
        startTime
      );

      rawAgentOutputs.coordinatorRaw = coordinatorRaw;
      tierResults[0].progress = 100;
      tierResults[0].status = 'completed';
      onTierComplete?.(tierResults[0]);

      console.log('✅ Tier 1 Complete: Budget Coordinator Agent finished');

      // TIER 2: Parallel Execution - Cost Calculator + Resource Estimator
      onProgress?.('💸 Tier 2: Parallel analysis - Cost calculation & Resource estimation...', 'Parallel Analysis', 40, 2);
      tierResults[1].status = 'running';

      // Execute both agents in parallel
      const [costCalculatorResult, resourceEstimatorResult] = await Promise.all([
        this.executeCostCalculatorAgent(coordinatorResult, project.id, startTime),
        this.executeResourceEstimatorAgent(coordinatorResult, project.id, startTime)
      ]);

      rawAgentOutputs.costCalculatorRaw = costCalculatorResult.rawResponse;
      rawAgentOutputs.resourceEstimatorRaw = resourceEstimatorResult.rawResponse;

      tierResults[1].progress = 100;
      tierResults[1].status = 'completed';
      onTierComplete?.(tierResults[1]);

      console.log('✅ Tier 2 Complete: Cost Calculator & Resource Estimator agents finished');

      // TIER 3: Optimization Scenario Agent - Budget Optimization
      onProgress?.('🎯 Tier 3: Budget optimization generating 4 scenarios...', 'Scenario Optimization', 75, 3);
      tierResults[2].status = 'running';

      const { result: optimizationResult, rawResponse: optimizationRaw } = await this.executeBudgetOptimizationAgent(
        coordinatorResult,
        costCalculatorResult.result,
        resourceEstimatorResult.result,
        project.id,
        startTime
      );

      rawAgentOutputs.optimizationRaw = optimizationRaw;
      tierResults[2].progress = 100;
      tierResults[2].status = 'completed';
      onTierComplete?.(tierResults[2]);

      console.log('✅ Tier 3 Complete: Budget Optimization Agent finished');

      // Final compilation and recommendation
      onProgress?.('📊 Compiling final budget analysis...', 'Final Analysis', 95, 3);

      const endTime = new Date().toISOString();
      const totalProcessingTime = new Date(endTime).getTime() - new Date(startTime).getTime();

      // Compile final results
      const finalResult: DepthBudgetResult = {
        projectId: project.id,
        executionMetadata: {
          startTime,
          endTime,
          totalProcessingTime,
          tierResults
        },
        scenarios: optimizationResult.scenarios || [],
        rawAgentOutputs,
        recommendedScenario: optimizationResult.recommendedScenario || 'cost-optimized',
        summary: {
          optimalBudget: optimizationResult.summary?.optimalBudget || 2500000,
          budgetRange: optimizationResult.summary?.budgetRange || '$2.2M - $2.8M',
          majorCostDrivers: optimizationResult.summary?.majorCostDrivers || ['Cast salaries', 'Equipment rentals', 'Location fees'],
          budgetRecommendations: optimizationResult.summary?.budgetRecommendations || ['Consider equipment purchase vs rental', 'Optimize location schedules', 'Negotiate cast deals']
        },
        complianceReport: optimizationResult.complianceReport
      };

      onProgress?.('✅ AI Depth Budget Analysis Complete!', 'Complete', 100, 3);
      console.log('🎉 Complete AI Depth Budget Analysis Pipeline Finished');

      return finalResult;

    } catch (error) {
      console.error('❌ Budget Analysis Pipeline Error:', error);

      // Mark current tier as failed
      const currentTier = tierResults.find(t => t.status === 'running');
      if (currentTier) {
        currentTier.status = 'failed';
      }

      // Return error result with available data
      return {
        projectId: project.id,
        executionMetadata: {
          startTime,
          endTime: new Date().toISOString(),
          totalProcessingTime: new Date().getTime() - new Date(startTime).getTime(),
          tierResults
        },
        scenarios: [],
        rawAgentOutputs,
        recommendedScenario: 'baseline',
        summary: {
          optimalBudget: 0,
          budgetRange: 'Analysis Failed',
          majorCostDrivers: ['Pipeline execution error'],
          budgetRecommendations: ['Restart analysis']
        }
      };
    }
  }

