  recommendedScenario: string;
  summary: {
    optimalBudget: number;
    budgetRange: string;
    majorCostDrivers: string[];
    budgetRecommendations: string[];
  };
  complianceReport?: {
    unionBudgetCompliance: any;
    insuranceRequirements: any;
    taxIncentiveOpportunities: any;
  };
}

