            const tierNum = parseInt(tier.split(' ')[1]);
            return prev.map(p => 
              p.tierNumber === tierNum 
                ? { ...p, progress, status: progress === 100 ? 'completed' : 'running' }
                : p
            );
          });
        }
      );

      setDepthBudgetResults(result);
      setBudgetScenarios(result.scenarios || []);

