    </div>
  </div>

  {/* Sub-categories if available */}
  {category.subCategories && category.subCategories.length > 0 && (
    <div className="mt-3 pt-3 border-t space-y-2">
      <h6 className="text-sm font-medium text-muted-foreground">Sub-categories:</h6>
