                          coordinator: setJsonInputBudgetCoordinator,
                          labor: setJsonInputLaborCost,
                          equipment: setJsonInputEquipmentPricing,
                          location: setJsonInputLocationCost,
                          schedule: setJsonInputScheduleOptimizer,
