      basicBudget: basicBudgetResult,
      masterBudget: masterBudgetResult,
      depthBudgetAnalysis: depthBudgetResults,
      budgetServices: {
        coordinator: budgetCoordinatorResult,
        laborCost: laborCostResult,
        equipmentPricing: equipmentPricingResult,
