        toast.success("Basic Budget Generated!", {
          description: `Total budget: $${result.result.basicBudgetOutput?.budgetSummary?.totalBudget?.toLocaleString() || 'N/A'}`,
        });
      } else {
        throw new Error(result.error || 'Basic budget generation failed');
