        selectedProject.name,
        scenario.scenarioName,
        scenario.budgetSummary?.totalBudget || 0,
        scenario.budgetSummary?.shootDays || 0,
        scenario.scenarioType === depthBudgetResults.recommendedScenario ? 'Yes' : 'No'
      ])
