      if (storedBasicBudget) {
        try {
          const budget = JSON.parse(storedBasicBudget);
          setBasicBudgetResult(budget);
          console.log('✅ Loaded basic budget data from localStorage');
        } catch (error) {
          console.error('Error loading stored basic budget:', error);
        }
