                      )}

                      {!expandedRawSections[activeTab] && (
                        <div className="text-sm text-muted-foreground">
                          Analysis completed successfully. Click "Show Details" to view full results.
                        </div>
                      )}
                    </div>
                  </CardContent>
                </Card>
              );
            })()}
          </div>
        )}
        </div>
      </div>
    </div>
  );
}

